window.HT = window.HT || {};
(HT.schedulerSeeds = HT.schedulerSeeds || {})["ap-csp"] = {"id":"ap-csp","title":"AP Computer Science Principles (big ideas)","courseTitle":"AP Computer Science Principles","subject":{"id":"ap-csp","label":"AP Computer Science Principles"},"source":"AP Computer Science Principles Course and Exam Description, effective Fall 2023","data":{"objectiveTrees":[{"id":"content","name":"AP CSP content","levels":["Big idea","Topic","Learning objective","Essential knowledge"],"nodes":[{"id":"c-1","parentId":null,"code":"1","text":"Creative Development","order":1,"origin":"template","meta":{"durationMeetings":14,"examWeighting":"10–13%","abbreviation":"CRD"}},{"id":"c-1.1","parentId":"c-1","code":"1.1","text":"Collaboration","order":1,"origin":"template","meta":{"durationMeetings":3}},{"id":"c-1.2","parentId":"c-1","code":"1.2","text":"Program Function and Purpose","order":2,"origin":"template","meta":{"durationMeetings":4}},{"id":"c-1.3","parentId":"c-1","code":"1.3","text":"Program Design and Development","order":3,"origin":"template","meta":{"durationMeetings":4}},{"id":"c-1.4","parentId":"c-1","code":"1.4","text":"Identifying and Correcting Errors","order":4,"origin":"template","meta":{"durationMeetings":3}},{"id":"c-2","parentId":null,"code":"2","text":"Data","order":2,"origin":"template","meta":{"durationMeetings":22,"examWeighting":"17–22%","abbreviation":"DAT"}},{"id":"c-2.1","parentId":"c-2","code":"2.1","text":"Binary Numbers","order":1,"origin":"template","meta":{"durationMeetings":6}},{"id":"c-2.2","parentId":"c-2","code":"2.2","text":"Data Compression","order":2,"origin":"template","meta":{"durationMeetings":4.5}},{"id":"c-2.3","parentId":"c-2","code":"2.3","text":"Extracting Information from Data","order":3,"origin":"template","meta":{"durationMeetings":6}},{"id":"c-2.4","parentId":"c-2","code":"2.4","text":"Using Programs with Data","order":4,"origin":"template","meta":{"durationMeetings":5}},{"id":"c-3","parentId":null,"code":"3","text":"Algorithms and Programming","order":3,"origin":"template","meta":{"durationMeetings":46,"examWeighting":"30–35%","abbreviation":"AAP"}},{"id":"c-3.1","parentId":"c-3","code":"3.1","text":"Variables and Assignments","order":1,"origin":"template","meta":{"durationMeetings":2.5}},{"id":"c-3.2","parentId":"c-3","code":"3.2","text":"Data Abstraction","order":2,"origin":"template","meta":{"durationMeetings":3.5}},{"id":"c-3.3","parentId":"c-3","code":"3.3","text":"Mathematical Expressions","order":3,"origin":"template","meta":{"durationMeetings":3.5}},{"id":"c-3.4","parentId":"c-3","code":"3.4","text":"Strings","order":4,"origin":"template","meta":{"durationMeetings":2}},{"id":"c-3.5","parentId":"c-3","code":"3.5","text":"Boolean Expressions","order":5,"origin":"template","meta":{"durationMeetings":2.5}},{"id":"c-3.6","parentId":"c-3","code":"3.6","text":"Conditionals","order":6,"origin":"template","meta":{"durationMeetings":2}},{"id":"c-3.7","parentId":"c-3","code":"3.7","text":"Nested Conditionals","order":7,"origin":"template","meta":{"durationMeetings":1.5}},{"id":"c-3.8","parentId":"c-3","code":"3.8","text":"Iteration","order":8,"origin":"template","meta":{"durationMeetings":2.5}},{"id":"c-3.9","parentId":"c-3","code":"3.9","text":"Developing Algorithms","order":9,"origin":"template","meta":{"durationMeetings":3}},{"id":"c-3.10","parentId":"c-3","code":"3.10","text":"Lists","order":10,"origin":"template","meta":{"durationMeetings":2.5}},{"id":"c-3.11","parentId":"c-3","code":"3.11","text":"Binary Search","order":11,"origin":"template","meta":{"durationMeetings":2}},{"id":"c-3.12","parentId":"c-3","code":"3.12","text":"Calling Procedures","order":12,"origin":"template","meta":{"durationMeetings":3}},{"id":"c-3.13","parentId":"c-3","code":"3.13","text":"Developing Procedures","order":13,"origin":"template","meta":{"durationMeetings":3}},{"id":"c-3.14","parentId":"c-3","code":"3.14","text":"Libraries","order":14,"origin":"template","meta":{"durationMeetings":2.5}},{"id":"c-3.15","parentId":"c-3","code":"3.15","text":"Random Values","order":15,"origin":"template","meta":{"durationMeetings":2}},{"id":"c-3.16","parentId":"c-3","code":"3.16","text":"Simulations","order":16,"origin":"template","meta":{"durationMeetings":3}},{"id":"c-3.17","parentId":"c-3","code":"3.17","text":"Algorithmic Efficiency","order":17,"origin":"template","meta":{"durationMeetings":3}},{"id":"c-3.18","parentId":"c-3","code":"3.18","text":"Undecidable Problems","order":18,"origin":"template","meta":{"durationMeetings":2}},{"id":"c-CPT","parentId":null,"code":"CPT","text":"Create Performance Task (at least 9 class hours)","order":4,"origin":"custom","meta":{"durationMeetings":12}},{"id":"c-4","parentId":null,"code":"4","text":"Computer Systems and Networks","order":5,"origin":"template","meta":{"durationMeetings":16,"examWeighting":"11–15%","abbreviation":"CSN"}},{"id":"c-4.1","parentId":"c-4","code":"4.1","text":"The Internet","order":1,"origin":"template","meta":{"durationMeetings":6.5}},{"id":"c-4.2","parentId":"c-4","code":"4.2","text":"Fault Tolerance","order":2,"origin":"template","meta":{"durationMeetings":4}},{"id":"c-4.3","parentId":"c-4","code":"4.3","text":"Parallel and Distributed Computing","order":3,"origin":"template","meta":{"durationMeetings":5}},{"id":"c-5","parentId":null,"code":"5","text":"Impact of Computing","order":6,"origin":"template","meta":{"durationMeetings":26,"examWeighting":"21–26%","abbreviation":"IOC"}},{"id":"c-5.1","parentId":"c-5","code":"5.1","text":"Beneficial and Harmful Effects","order":1,"origin":"template","meta":{"durationMeetings":4.5}},{"id":"c-5.2","parentId":"c-5","code":"5.2","text":"Digital Divide","order":2,"origin":"template","meta":{"durationMeetings":3.5}},{"id":"c-5.3","parentId":"c-5","code":"5.3","text":"Computing Bias","order":3,"origin":"template","meta":{"durationMeetings":3}},{"id":"c-5.4","parentId":"c-5","code":"5.4","text":"Crowdsourcing","order":4,"origin":"template","meta":{"durationMeetings":3.5}},{"id":"c-5.5","parentId":"c-5","code":"5.5","text":"Legal and Ethical Concerns","order":5,"origin":"template","meta":{"durationMeetings":4.5}},{"id":"c-5.6","parentId":"c-5","code":"5.6","text":"Safe Computing","order":6,"origin":"template","meta":{"durationMeetings":7}},{"id":"c-CRD-1.A","parentId":"c-1.1","code":"CRD-1.A","text":"Explain how computing innovations are improved through collaboration.","order":1,"origin":"template","meta":{"enduringUnderstanding":"CRD-1: Incorporating multiple perspectives through collaboration improves computing innovations as they are developed.","skills":["1.C"]}},{"id":"c-CRD-1.A.1","parentId":"c-CRD-1.A","code":"CRD-1.A.1","text":"A computing innovation includes a program as an integral part of its function.","order":1,"origin":"template"},{"id":"c-CRD-1.A.2","parentId":"c-CRD-1.A","code":"CRD-1.A.2","text":"A computing innovation can be physical (e.g., self-driving car), nonphysical computing software (e.g., picture editing software), or a nonphysical computing concept (e.g., e-commerce).","order":2,"origin":"template"},{"id":"c-CRD-1.A.3","parentId":"c-CRD-1.A","code":"CRD-1.A.3","text":"Effective collaboration produces a computing innovation that reflects the diversity of talents and perspectives of those who designed it.","order":3,"origin":"template"},{"id":"c-CRD-1.A.4","parentId":"c-CRD-1.A","code":"CRD-1.A.4","text":"Collaboration that includes diverse perspectives helps avoid bias in the development of computing innovations.","order":4,"origin":"template"},{"id":"c-CRD-1.A.5","parentId":"c-CRD-1.A","code":"CRD-1.A.5","text":"Consultation and communication with users are important aspects of the development of computing innovations.","order":5,"origin":"template"},{"id":"c-CRD-1.A.6","parentId":"c-CRD-1.A","code":"CRD-1.A.6","text":"Information gathered from potential users can be used to understand the purpose of a program from diverse perspectives and to develop a program that fully incorporates these perspectives.","order":6,"origin":"template"},{"id":"c-CRD-1.B","parentId":"c-1.1","code":"CRD-1.B","text":"Explain how computing innovations are developed by groups of people.","order":2,"origin":"template","meta":{"enduringUnderstanding":"CRD-1: Incorporating multiple perspectives through collaboration improves computing innovations as they are developed.","skills":["1.C"]}},{"id":"c-CRD-1.B.1","parentId":"c-CRD-1.B","code":"CRD-1.B.1","text":"Online tools support collaboration by allowing programmers to share and provide feedback on ideas and documents.","order":1,"origin":"template"},{"id":"c-CRD-1.B.2","parentId":"c-CRD-1.B","code":"CRD-1.B.2","text":"Common models such as pair programming exist to facilitate collaboration.","order":2,"origin":"template"},{"id":"c-CRD-1.C","parentId":"c-1.1","code":"CRD-1.C","text":"Demonstrate effective interpersonal skills during collaboration.","order":3,"origin":"template","meta":{"enduringUnderstanding":"CRD-1: Incorporating multiple perspectives through collaboration improves computing innovations as they are developed.","skills":["1.C"]}},{"id":"c-CRD-1.C.1","parentId":"c-CRD-1.C","code":"CRD-1.C.1","text":"Effective collaborative teams practice interpersonal skills, including but not limited to:","order":1,"origin":"template"},{"id":"c-CRD-2.A","parentId":"c-1.2","code":"CRD-2.A","text":"Describe the purpose of a computing innovation.","order":1,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking.","skills":["1.A"]}},{"id":"c-CRD-2.A.1","parentId":"c-CRD-2.A","code":"CRD-2.A.1","text":"The purpose of computing innovations is to solve problems or to pursue interests through creative expression.","order":1,"origin":"template"},{"id":"c-CRD-2.A.2","parentId":"c-CRD-2.A","code":"CRD-2.A.2","text":"An understanding of the purpose of a computing innovation provides developers with an improved ability to develop that computing innovation.","order":2,"origin":"template"},{"id":"c-CRD-2.B","parentId":"c-1.2","code":"CRD-2.B","text":"Explain how a program or code segment functions.","order":2,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking."}},{"id":"c-CRD-2.B.1","parentId":"c-CRD-2.B","code":"CRD-2.B.1","text":"A program is a collection of program statements that performs a specific task when run by a computer. A program is often referred to as software.","order":1,"origin":"template"},{"id":"c-CRD-2.B.2","parentId":"c-CRD-2.B","code":"CRD-2.B.2","text":"A code segment is a collection of program statements that is part of a program.","order":2,"origin":"template"},{"id":"c-CRD-2.B.3","parentId":"c-CRD-2.B","code":"CRD-2.B.3","text":"A program needs to work for a variety of inputs and situations.","order":3,"origin":"template"},{"id":"c-CRD-2.B.4","parentId":"c-CRD-2.B","code":"CRD-2.B.4","text":"The behavior of a program is how a program functions during execution and is often described by how a user interacts with it.","order":4,"origin":"template"},{"id":"c-CRD-2.B.5","parentId":"c-CRD-2.B","code":"CRD-2.B.5","text":"A program can be described broadly by what it does, or in more detail by both what the program does and how the program statements accomplish this function.","order":5,"origin":"template"},{"id":"c-CRD-2.C","parentId":"c-1.2","code":"CRD-2.C","text":"Identify input(s) to a program.","order":3,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking."}},{"id":"c-CRD-2.C.1","parentId":"c-CRD-2.C","code":"CRD-2.C.1","text":"Program inputs are data sent to a computer for processing by a program. Input can come in a variety of forms, such as tactile, audio, visual, or text.","order":1,"origin":"template"},{"id":"c-CRD-2.C.2","parentId":"c-CRD-2.C","code":"CRD-2.C.2","text":"An event is associated with an action and supplies input data to a program.","order":2,"origin":"template"},{"id":"c-CRD-2.C.3","parentId":"c-CRD-2.C","code":"CRD-2.C.3","text":"Events can be generated when a key is pressed, a mouse is clicked, a program is started, or any other defined action occurs that affects the flow of execution.","order":3,"origin":"template"},{"id":"c-CRD-2.C.4","parentId":"c-CRD-2.C","code":"CRD-2.C.4","text":"Inputs usually affect the output produced by a program.","order":4,"origin":"template"},{"id":"c-CRD-2.C.5","parentId":"c-CRD-2.C","code":"CRD-2.C.5","text":"In event-driven programming, program statements are executed when triggered rather than through the sequential flow of control.","order":5,"origin":"template"},{"id":"c-CRD-2.C.6","parentId":"c-CRD-2.C","code":"CRD-2.C.6","text":"Input can come from a user or other programs.","order":6,"origin":"template"},{"id":"c-CRD-2.D","parentId":"c-1.2","code":"CRD-2.D","text":"Identify output(s) produced by a program.","order":4,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking.","skills":["3.A"]}},{"id":"c-CRD-2.D.1","parentId":"c-CRD-2.D","code":"CRD-2.D.1","text":"Program outputs are any data sent from a program to a device. Program output can come in a variety of forms, such as tactile, audio, visual, or text.","order":1,"origin":"template"},{"id":"c-CRD-2.D.2","parentId":"c-CRD-2.D","code":"CRD-2.D.2","text":"Program output is usually based on a program’s input or prior state (e.g., internal values).","order":2,"origin":"template"},{"id":"c-CRD-2.E","parentId":"c-1.3","code":"CRD-2.E","text":"Develop a program using a development process.","order":1,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking.","skills":["1.B"]}},{"id":"c-CRD-2.E.1","parentId":"c-CRD-2.E","code":"CRD-2.E.1","text":"A development process can be ordered and intentional, or exploratory in nature.","order":1,"origin":"template"},{"id":"c-CRD-2.E.2","parentId":"c-CRD-2.E","code":"CRD-2.E.2","text":"There are multiple development processes. The following phases are commonly used when developing a program:","order":2,"origin":"template"},{"id":"c-CRD-2.E.3","parentId":"c-CRD-2.E","code":"CRD-2.E.3","text":"A development process that is iterative requires refinement and revision based on feedback, testing, or reflection throughout the process. This may require revisiting earlier phases of the process.","order":3,"origin":"template"},{"id":"c-CRD-2.E.4","parentId":"c-CRD-2.E","code":"CRD-2.E.4","text":"A development process that is incremental is one that breaks the problem into smaller pieces and makes sure each piece works before adding it to the whole.","order":4,"origin":"template"},{"id":"c-CRD-2.F","parentId":"c-1.3","code":"CRD-2.F","text":"Design a program and its user interface.","order":2,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking.","skills":["1.B"]}},{"id":"c-CRD-2.F.1","parentId":"c-CRD-2.F","code":"CRD-2.F.1","text":"The design of a program incorporates investigation to determine its requirements.","order":1,"origin":"template"},{"id":"c-CRD-2.F.2","parentId":"c-CRD-2.F","code":"CRD-2.F.2","text":"Investigation in a development process is useful for understanding and identifying the program constraints, as well as the concerns and interests of the people who will use the program.","order":2,"origin":"template"},{"id":"c-CRD-2.F.3","parentId":"c-CRD-2.F","code":"CRD-2.F.3","text":"Some ways investigation can be performed are as follows:","order":3,"origin":"template"},{"id":"c-CRD-2.F.4","parentId":"c-CRD-2.F","code":"CRD-2.F.4","text":"Program requirements describe how a program functions and may include a description of user interactions that a program must provide.","order":4,"origin":"template"},{"id":"c-CRD-2.F.5","parentId":"c-CRD-2.F","code":"CRD-2.F.5","text":"A program’s specification defines the requirements for the program.","order":5,"origin":"template"},{"id":"c-CRD-2.F.6","parentId":"c-CRD-2.F","code":"CRD-2.F.6","text":"In a development process, the design phase outlines how to accomplish a given program specification.","order":6,"origin":"template"},{"id":"c-CRD-2.F.7","parentId":"c-CRD-2.F","code":"CRD-2.F.7","text":"The design phase of a program may include:","order":7,"origin":"template"},{"id":"c-CRD-2.G","parentId":"c-1.3","code":"CRD-2.G","text":"Describe the purpose of a code segment or program by writing documentation.","order":3,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking.","skills":["4.A"]}},{"id":"c-CRD-2.G.1","parentId":"c-CRD-2.G","code":"CRD-2.G.1","text":"Program documentation is a written description of the function of a code segment, event, procedure, or program and how it was developed.","order":1,"origin":"template"},{"id":"c-CRD-2.G.2","parentId":"c-CRD-2.G","code":"CRD-2.G.2","text":"Comments are a form of program documentation written into the program to be read by people and do not affect how a program runs.","order":2,"origin":"template"},{"id":"c-CRD-2.G.3","parentId":"c-CRD-2.G","code":"CRD-2.G.3","text":"Programmers should document a program throughout its development.","order":3,"origin":"template"},{"id":"c-CRD-2.G.4","parentId":"c-CRD-2.G","code":"CRD-2.G.4","text":"Program documentation helps in developing and maintaining correct programs when working individually or in collaborative programming environments.","order":4,"origin":"template"},{"id":"c-CRD-2.G.5","parentId":"c-CRD-2.G","code":"CRD-2.G.5","text":"Not all programming environments support comments, so other methods of documentation may be required.","order":5,"origin":"template"},{"id":"c-CRD-2.H","parentId":"c-1.3","code":"CRD-2.H","text":"Acknowledge code segments used from other sources.","order":4,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking."}},{"id":"c-CRD-2.H.1","parentId":"c-CRD-2.H","code":"CRD-2.H.1","text":"It is important to acknowledge any code segments that were developed collaboratively or by another source.","order":1,"origin":"template"},{"id":"c-CRD-2.H.2","parentId":"c-CRD-2.H","code":"CRD-2.H.2","text":"Acknowledgement of a code segment(s) written by someone else and used in a program can be in the program documentation. The acknowledgement should include the origin or original author’s name.","order":2,"origin":"template"},{"id":"c-CRD-2.I","parentId":"c-1.4","code":"CRD-2.I","text":"For errors in an algorithm or program: a. Identify the error. 4.C b. Correct the error.","order":1,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking.","skills":["4.C"]}},{"id":"c-CRD-2.I.1","parentId":"c-CRD-2.I","code":"CRD-2.I.1","text":"A logic error is a mistake in the algorithm or program that causes it to behave incorrectly or unexpectedly.","order":1,"origin":"template"},{"id":"c-CRD-2.I.2","parentId":"c-CRD-2.I","code":"CRD-2.I.2","text":"A syntax error is a mistake in the program where the rules of the programming language are not followed.","order":2,"origin":"template"},{"id":"c-CRD-2.I.3","parentId":"c-CRD-2.I","code":"CRD-2.I.3","text":"A run-time error is a mistake in the program that occurs during the execution of a program. Programming languages define their own run-time errors.","order":3,"origin":"template"},{"id":"c-CRD-2.I.4","parentId":"c-CRD-2.I","code":"CRD-2.I.4","text":"An overflow error is an error that occurs when a computer attempts to handle a number that is outside of the defined range of values.","order":4,"origin":"template"},{"id":"c-CRD-2.I.5","parentId":"c-CRD-2.I","code":"CRD-2.I.5","text":"The following are effective ways to find and correct errors:","order":5,"origin":"template"},{"id":"c-CRD-2.J","parentId":"c-1.4","code":"CRD-2.J","text":"Identify inputs and corresponding expected outputs or behaviors that can be used to check the correctness of an algorithm or program.","order":2,"origin":"template","meta":{"enduringUnderstanding":"CRD-2: Developers create and innovate using an iterative design process that is user-focused, that incorporates implementation/feedback cycles, and that leaves ample room for experimentation and risk-taking.","skills":["4.C"]}},{"id":"c-CRD-2.J.1","parentId":"c-CRD-2.J","code":"CRD-2.J.1","text":"In the development process, testing uses defined inputs to ensure that an algorithm or program is producing the expected outcomes. Programmers use the results from testing to revise their algorithms or programs.","order":1,"origin":"template"},{"id":"c-CRD-2.J.2","parentId":"c-CRD-2.J","code":"CRD-2.J.2","text":"Defined inputs used to test a program should demonstrate the different expected outcomes that are at or just beyond the extremes (minimum and maximum) of input data.","order":2,"origin":"template"},{"id":"c-CRD-2.J.3","parentId":"c-CRD-2.J","code":"CRD-2.J.3","text":"Program requirements are needed to identify appropriate defined inputs for testing.","order":3,"origin":"template"},{"id":"c-DAT-1.A","parentId":"c-2.1","code":"DAT-1.A","text":"Explain how data can be represented using bits.","order":1,"origin":"template","meta":{"enduringUnderstanding":"DAT-1: The way a computer represents data internally is different from the way the data are interpreted and displayed for the user. Programs are used to translate data into a representation more easily understood by people.","skills":["3.C"]}},{"id":"c-DAT-1.A.1","parentId":"c-DAT-1.A","code":"DAT-1.A.1","text":"Data values can be stored in variables, lists of items, or standalone constants and can be passed as input to (or output from) procedures.","order":1,"origin":"template"},{"id":"c-DAT-1.A.2","parentId":"c-DAT-1.A","code":"DAT-1.A.2","text":"Computing devices represent data digitally, meaning that the lowest-level components of any value are bits.","order":2,"origin":"template"},{"id":"c-DAT-1.A.3","parentId":"c-DAT-1.A","code":"DAT-1.A.3","text":"Bit is shorthand for binary digit and is either 0 or 1.","order":3,"origin":"template"},{"id":"c-DAT-1.A.4","parentId":"c-DAT-1.A","code":"DAT-1.A.4","text":"A byte is 8 bits.","order":4,"origin":"template"},{"id":"c-DAT-1.A.5","parentId":"c-DAT-1.A","code":"DAT-1.A.5","text":"Abstraction is the process of reducing complexity by focusing on the main idea. By hiding details irrelevant to the question at hand and bringing together related and useful details, abstraction reduces complexity and allows one to focus on the idea.","order":5,"origin":"template"},{"id":"c-DAT-1.A.6","parentId":"c-DAT-1.A","code":"DAT-1.A.6","text":"Bits are grouped to represent abstractions. These abstractions include, but are not limited to, numbers, characters, and color.","order":6,"origin":"template"},{"id":"c-DAT-1.A.7","parentId":"c-DAT-1.A","code":"DAT-1.A.7","text":"The same sequence of bits may represent different types of data in different contexts.","order":7,"origin":"template"},{"id":"c-DAT-1.A.8","parentId":"c-DAT-1.A","code":"DAT-1.A.8","text":"Analog data have values that change smoothly, rather than in discrete intervals, over time. Some examples of analog data include pitch and volume of music, colors of a painting, or position of a sprinter during a race.","order":8,"origin":"template"},{"id":"c-DAT-1.A.9","parentId":"c-DAT-1.A","code":"DAT-1.A.9","text":"The use of digital data to approximate real-world analog data is an example of abstraction.","order":9,"origin":"template"},{"id":"c-DAT-1.A.10","parentId":"c-DAT-1.A","code":"DAT-1.A.10","text":"Analog data can be closely approximated digitally using a sampling technique, which means measuring values of the analog signal at regular intervals called samples. The samples are measured to figure out the exact bits required to store each sample.","order":10,"origin":"template"},{"id":"c-DAT-1.B","parentId":"c-2.1","code":"DAT-1.B","text":"Explain the consequences of using bits to represent data.","order":2,"origin":"template","meta":{"enduringUnderstanding":"DAT-1: The way a computer represents data internally is different from the way the data are interpreted and displayed for the user. Programs are used to translate data into a representation more easily understood by people."}},{"id":"c-DAT-1.B.1","parentId":"c-DAT-1.B","code":"DAT-1.B.1","text":"In many programming languages, integers are represented by a fixed number of bits, which limits the range of integer values and mathematical operations on those values. This limitation can result in overflow or other errors.","order":1,"origin":"template"},{"id":"c-DAT-1.B.2","parentId":"c-DAT-1.B","code":"DAT-1.B.2","text":"Other programming languages provide an abstraction through which the size of representable integers is limited only by the size of the computer’s memory; this is the case for the language defined in the exam reference sheet.","order":2,"origin":"template"},{"id":"c-DAT-1.B.3","parentId":"c-DAT-1.B","code":"DAT-1.B.3","text":"In programming languages, the fixed number of bits used to represent real numbers limits the range and mathematical operations on these values; this limitation can result in round-off and other errors. Some real numbers are represented as approximations in computer storage. [Exclusion statement: EK DAT-1.B.3): Specific range limitations for real numbers are outside the scope of this course and the AP Exam.]","order":3,"origin":"template","meta":{"exclusion":"EK DAT-1.B.3): Specific range limitations for real numbers are outside the scope of this course and the AP Exam."}},{"id":"c-DAT-1.C","parentId":"c-2.1","code":"DAT-1.C","text":"For binary numbers: a. Calculate the binary (base 2) equivalent of a positive integer (base 10) and vice versa. 2.B b. Compare and order binary numbers.","order":3,"origin":"template","meta":{"enduringUnderstanding":"DAT-1: The way a computer represents data internally is different from the way the data are interpreted and displayed for the user. Programs are used to translate data into a representation more easily understood by people.","skills":["2.B"]}},{"id":"c-DAT-1.C.1","parentId":"c-DAT-1.C","code":"DAT-1.C.1","text":"Number bases, including binary and decimal, are used to represent data.","order":1,"origin":"template"},{"id":"c-DAT-1.C.2","parentId":"c-DAT-1.C","code":"DAT-1.C.2","text":"Binary (base 2) uses only combinations of the digits zero and one.","order":2,"origin":"template"},{"id":"c-DAT-1.C.3","parentId":"c-DAT-1.C","code":"DAT-1.C.3","text":"Decimal (base 10) uses only combinations of the digits 0 – 9.","order":3,"origin":"template"},{"id":"c-DAT-1.C.4","parentId":"c-DAT-1.C","code":"DAT-1.C.4","text":"As with decimal, a digit’s position in the binary sequence determines its numeric value. The numeric value is equal to the bit’s value (0 or 1) multiplied by the place value of its position.","order":4,"origin":"template"},{"id":"c-DAT-1.C.5","parentId":"c-DAT-1.C","code":"DAT-1.C.5","text":"The place value of each position is determined by the base raised to the power of the position. Positions are numbered starting at the rightmost position with 0 and increasing by 1 for each subsequent position to the left.","order":5,"origin":"template"},{"id":"c-DAT-1.D","parentId":"c-2.2","code":"DAT-1.D","text":"Compare data compression algorithms to determine which is best in a particular context.","order":1,"origin":"template","meta":{"enduringUnderstanding":"DAT-1: The way a computer represents data internally is different from the way the data are interpreted and displayed for the user. Programs are used to translate data into a representation more easily understood by people.","skills":["1.D"]}},{"id":"c-DAT-1.D.1","parentId":"c-DAT-1.D","code":"DAT-1.D.1","text":"Data compression can reduce the size (number of bits) of transmitted or stored data.","order":1,"origin":"template"},{"id":"c-DAT-1.D.2","parentId":"c-DAT-1.D","code":"DAT-1.D.2","text":"Fewer bits does not necessarily mean less information.","order":2,"origin":"template"},{"id":"c-DAT-1.D.3","parentId":"c-DAT-1.D","code":"DAT-1.D.3","text":"The amount of size reduction from compression depends on both the amount of redundancy in the original data representation and the compression algorithm applied.","order":3,"origin":"template"},{"id":"c-DAT-1.D.4","parentId":"c-DAT-1.D","code":"DAT-1.D.4","text":"Lossless data compression algorithms can usually reduce the number of bits stored or transmitted while guaranteeing complete reconstruction of the original data.","order":4,"origin":"template"},{"id":"c-DAT-1.D.5","parentId":"c-DAT-1.D","code":"DAT-1.D.5","text":"Lossy data compression algorithms can significantly reduce the number of bits stored or transmitted but only allow reconstruction of an approximation of the original data.","order":5,"origin":"template"},{"id":"c-DAT-1.D.6","parentId":"c-DAT-1.D","code":"DAT-1.D.6","text":"Lossy data compression algorithms can usually reduce the number of bits stored or transmitted more than lossless compression algorithms.","order":6,"origin":"template"},{"id":"c-DAT-1.D.7","parentId":"c-DAT-1.D","code":"DAT-1.D.7","text":"In situations where quality or ability to reconstruct the original is maximally important, lossless compression algorithms are typically chosen.","order":7,"origin":"template"},{"id":"c-DAT-1.D.8","parentId":"c-DAT-1.D","code":"DAT-1.D.8","text":"In situations where minimizing data size or transmission time is maximally important, lossy compression algorithms are typically chosen.","order":8,"origin":"template"},{"id":"c-DAT-2.A","parentId":"c-2.3","code":"DAT-2.A","text":"Describe what information can be extracted from data.","order":1,"origin":"template","meta":{"enduringUnderstanding":"DAT-2: Programs can be used to process data, which allows users to discover information and create new knowledge."}},{"id":"c-DAT-2.A.1","parentId":"c-DAT-2.A","code":"DAT-2.A.1","text":"Information is the collection of facts and patterns extracted from data.","order":1,"origin":"template"},{"id":"c-DAT-2.A.2","parentId":"c-DAT-2.A","code":"DAT-2.A.2","text":"Data provide opportunities for identifying trends, making connections, and addressing problems.","order":2,"origin":"template"},{"id":"c-DAT-2.A.3","parentId":"c-DAT-2.A","code":"DAT-2.A.3","text":"Digitally processed data may show correlation between variables. A correlation found in data does not necessarily indicate that a causal relationship exists. Additional research is needed to understand the exact nature of the relationship.","order":3,"origin":"template"},{"id":"c-DAT-2.A.4","parentId":"c-DAT-2.A","code":"DAT-2.A.4","text":"Often, a single source does not contain the data needed to draw a conclusion. It may be necessary to combine data from a variety of sources to formulate a conclusion.","order":4,"origin":"template"},{"id":"c-DAT-2.B","parentId":"c-2.3","code":"DAT-2.B","text":"Describe what information can be extracted from metadata.","order":2,"origin":"template","meta":{"enduringUnderstanding":"DAT-2: Programs can be used to process data, which allows users to discover information and create new knowledge.","skills":["5.B"]}},{"id":"c-DAT-2.B.1","parentId":"c-DAT-2.B","code":"DAT-2.B.1","text":"Metadata are data about data. For example, the piece of data may be an image, while the metadata may include the date of creation or the file size of the image.","order":1,"origin":"template"},{"id":"c-DAT-2.B.2","parentId":"c-DAT-2.B","code":"DAT-2.B.2","text":"Changes and deletions made to metadata do not change the primary data.","order":2,"origin":"template"},{"id":"c-DAT-2.B.3","parentId":"c-DAT-2.B","code":"DAT-2.B.3","text":"Metadata are used for finding, organizing, and managing information.","order":3,"origin":"template"},{"id":"c-DAT-2.B.4","parentId":"c-DAT-2.B","code":"DAT-2.B.4","text":"Metadata can increase the effective use of data or data sets by providing additional information.","order":4,"origin":"template"},{"id":"c-DAT-2.B.5","parentId":"c-DAT-2.B","code":"DAT-2.B.5","text":"Metadata allow data to be structured and organized.","order":5,"origin":"template"},{"id":"c-DAT-2.C","parentId":"c-2.3","code":"DAT-2.C","text":"Identify the challenges associated with processing data.","order":3,"origin":"template","meta":{"enduringUnderstanding":"DAT-2: Programs can be used to process data, which allows users to discover information and create new knowledge.","skills":["5.D"]}},{"id":"c-DAT-2.C.1","parentId":"c-DAT-2.C","code":"DAT-2.C.1","text":"The ability to process data depends on the capabilities of the users and their tools.","order":1,"origin":"template"},{"id":"c-DAT-2.C.2","parentId":"c-DAT-2.C","code":"DAT-2.C.2","text":"Data sets pose challenges regardless of size, such as:","order":2,"origin":"template"},{"id":"c-DAT-2.C.3","parentId":"c-DAT-2.C","code":"DAT-2.C.3","text":"Depending on how data were collected, they may not be uniform. For example, if users enter data into an open field, the way they choose to abbreviate, spell, or capitalize something may vary from user to user.","order":3,"origin":"template"},{"id":"c-DAT-2.C.4","parentId":"c-DAT-2.C","code":"DAT-2.C.4","text":"Cleaning data is a process that makes the data uniform without changing their meaning (e.g., replacing all equivalent abbreviations, spellings, and capitalizations with the same word).","order":4,"origin":"template"},{"id":"c-DAT-2.C.5","parentId":"c-DAT-2.C","code":"DAT-2.C.5","text":"Problems of bias are often created by the type or source of data being collected. Bias is not eliminated by simply collecting more data.","order":5,"origin":"template"},{"id":"c-DAT-2.C.6","parentId":"c-DAT-2.C","code":"DAT-2.C.6","text":"The size of a data set affects the amount of information that can be extracted from it.","order":6,"origin":"template"},{"id":"c-DAT-2.C.7","parentId":"c-DAT-2.C","code":"DAT-2.C.7","text":"Large data sets are difficult to process using a single computer and may require parallel systems.","order":7,"origin":"template"},{"id":"c-DAT-2.C.8","parentId":"c-DAT-2.C","code":"DAT-2.C.8","text":"Scalability of systems is an important consideration when working with data sets, as the computational capacity of a system affects how data sets can be processed and stored.","order":8,"origin":"template"},{"id":"c-DAT-2.D","parentId":"c-2.4","code":"DAT-2.D","text":"Extract information from data using a program.","order":1,"origin":"template","meta":{"enduringUnderstanding":"DAT-2: Programs can be used to process data, which allows users to discover information and create new knowledge.","skills":["2.B"]}},{"id":"c-DAT-2.D.1","parentId":"c-DAT-2.D","code":"DAT-2.D.1","text":"Programs can be used to process data to acquire information.","order":1,"origin":"template"},{"id":"c-DAT-2.D.2","parentId":"c-DAT-2.D","code":"DAT-2.D.2","text":"Tables, diagrams, text, and other visual tools can be used to communicate insight and knowledge gained from data.","order":2,"origin":"template"},{"id":"c-DAT-2.D.3","parentId":"c-DAT-2.D","code":"DAT-2.D.3","text":"Search tools are useful for efficiently finding information.","order":3,"origin":"template"},{"id":"c-DAT-2.D.4","parentId":"c-DAT-2.D","code":"DAT-2.D.4","text":"Data filtering systems are important tools for finding information and recognizing patterns in data.","order":4,"origin":"template"},{"id":"c-DAT-2.D.5","parentId":"c-DAT-2.D","code":"DAT-2.D.5","text":"Programs such as spreadsheets help efficiently organize and find trends in information.","order":5,"origin":"template"},{"id":"c-DAT-2.D.6","parentId":"c-DAT-2.D","code":"DAT-2.D.6","text":"Some processes that can be used to extract or modify information from data include the following:","order":6,"origin":"template"},{"id":"c-DAT-2.E","parentId":"c-2.4","code":"DAT-2.E","text":"Explain how programs can be used to gain insight and knowledge from data.","order":2,"origin":"template","meta":{"enduringUnderstanding":"DAT-2: Programs can be used to process data, which allows users to discover information and create new knowledge.","skills":["5.B"]}},{"id":"c-DAT-2.E.1","parentId":"c-DAT-2.E","code":"DAT-2.E.1","text":"Programs are used in an iterative and interactive way when processing information to allow users to gain insight and knowledge about data.","order":1,"origin":"template"},{"id":"c-DAT-2.E.2","parentId":"c-DAT-2.E","code":"DAT-2.E.2","text":"Programmers can use programs to filter and clean digital data, thereby gaining insight and knowledge.","order":2,"origin":"template"},{"id":"c-DAT-2.E.3","parentId":"c-DAT-2.E","code":"DAT-2.E.3","text":"Combining data sources, clustering data, and classifying data are parts of the process of using programs to gain insight and knowledge from data.","order":3,"origin":"template"},{"id":"c-DAT-2.E.4","parentId":"c-DAT-2.E","code":"DAT-2.E.4","text":"Insight and knowledge can be obtained from translating and transforming digitally represented information.","order":4,"origin":"template"},{"id":"c-DAT-2.E.5","parentId":"c-DAT-2.E","code":"DAT-2.E.5","text":"Patterns can emerge when data are transformed using programs.","order":5,"origin":"template"},{"id":"c-AAP-1.A","parentId":"c-3.1","code":"AAP-1.A","text":"Represent a value with a variable.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-1: To find specific solutions to generalizable problems, programmers represent and organize data in multiple ways.","skills":["3.A"]}},{"id":"c-AAP-1.A.1","parentId":"c-AAP-1.A","code":"AAP-1.A.1","text":"A variable is an abstraction inside a program that can hold a value. Each variable has associated data storage that represents one value at a time, but that value can be a list or other collection that in turn contains multiple values.","order":1,"origin":"template"},{"id":"c-AAP-1.A.2","parentId":"c-AAP-1.A","code":"AAP-1.A.2","text":"Using meaningful variable names helps with the readability of program code and understanding of what values are represented by the variables.","order":2,"origin":"template"},{"id":"c-AAP-1.A.3","parentId":"c-AAP-1.A","code":"AAP-1.A.3","text":"Some programming languages provide types to represent data, which are referenced using variables. These types include numbers, Booleans, lists, and strings.","order":3,"origin":"template"},{"id":"c-AAP-1.A.4","parentId":"c-AAP-1.A","code":"AAP-1.A.4","text":"Some values are better suited to representation using one type of datum rather than another.","order":4,"origin":"template"},{"id":"c-AAP-1.B","parentId":"c-3.1","code":"AAP-1.B","text":"Determine the value of a variable as a result of an assignment.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-1: To find specific solutions to generalizable problems, programmers represent and organize data in multiple ways.","skills":["4.B"]}},{"id":"c-AAP-1.B.1","parentId":"c-AAP-1.B","code":"AAP-1.B.1","text":"The assignment operator allows a program to change the value represented by a variable.","order":1,"origin":"template"},{"id":"c-AAP-1.B.2","parentId":"c-AAP-1.B","code":"AAP-1.B.2","text":"The exam reference sheet provides the “ ” operator to use for assignment. For example, Text: a expression Block: a expression evaluates expression and then assigns a copy of the result to the variable a.","order":2,"origin":"template"},{"id":"c-AAP-1.B.3","parentId":"c-AAP-1.B","code":"AAP-1.B.3","text":"The value stored in a variable will be the most recent value assigned. For example: a 1 b a a 2 display(b) still displays 1.","order":3,"origin":"template"},{"id":"c-AAP-1.C","parentId":"c-3.2","code":"AAP-1.C","text":"Represent a list or string using a variable.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-1: To find specific solutions to generalizable problems, programmers represent and organize data in multiple ways.","skills":["3.A"]}},{"id":"c-AAP-1.C.1","parentId":"c-AAP-1.C","code":"AAP-1.C.1","text":"A list is an ordered sequence of elements. For example, [value1, value2, value3,...] describes a list where value1 is the first element, value2 is the second element, value3 is the third element, and so on.","order":1,"origin":"template"},{"id":"c-AAP-1.C.2","parentId":"c-AAP-1.C","code":"AAP-1.C.2","text":"An element is an individual value in a list that is assigned a unique index.","order":2,"origin":"template"},{"id":"c-AAP-1.C.3","parentId":"c-AAP-1.C","code":"AAP-1.C.3","text":"An index is a common method for referencing the elements in a list or string using natural numbers.","order":3,"origin":"template"},{"id":"c-AAP-1.C.4","parentId":"c-AAP-1.C","code":"AAP-1.C.4","text":"A string is an ordered sequence of characters.","order":4,"origin":"template"},{"id":"c-AAP-1.D","parentId":"c-3.2","code":"AAP-1.D","text":"For data abstraction: a. Develop data abstraction using lists to store multiple elements. 3.B b. Explain how the use of data abstraction manages complexity in program code.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-1: To find specific solutions to generalizable problems, programmers represent and organize data in multiple ways.","skills":["3.C"]}},{"id":"c-AAP-1.D.1","parentId":"c-AAP-1.D","code":"AAP-1.D.1","text":"Data abstraction provides a separation between the abstract properties of a data type and the concrete details of its representation.","order":1,"origin":"template"},{"id":"c-AAP-1.D.2","parentId":"c-AAP-1.D","code":"AAP-1.D.2","text":"Data abstractions manage complexity in programs by giving a collection of data a name without referencing the specific details of the representation.","order":2,"origin":"template"},{"id":"c-AAP-1.D.3","parentId":"c-AAP-1.D","code":"AAP-1.D.3","text":"Data abstractions can be created using lists.","order":3,"origin":"template"},{"id":"c-AAP-1.D.4","parentId":"c-AAP-1.D","code":"AAP-1.D.4","text":"Developing a data abstraction to implement in a program can result in a program that is easier to develop and maintain.","order":4,"origin":"template"},{"id":"c-AAP-1.D.5","parentId":"c-AAP-1.D","code":"AAP-1.D.5","text":"Data abstractions often contain different types of elements.","order":5,"origin":"template"},{"id":"c-AAP-1.D.6","parentId":"c-AAP-1.D","code":"AAP-1.D.6","text":"The use of lists allows multiple related items to be treated as a single value. Lists are referred to by different names, such as array, depending on the programming language. [Exclusion statement: EK APP-1.D.6): The use of linked lists is outside the scope of this course and the AP Exam.]","order":6,"origin":"template","meta":{"exclusion":"EK APP-1.D.6): The use of linked lists is outside the scope of this course and the AP Exam."}},{"id":"c-AAP-1.D.7","parentId":"c-AAP-1.D","code":"AAP-1.D.7","text":"The exam reference sheet provides the notation [value1, value2, value3,...] to create a list with those values as the first, second, third, and so on items. For example,","order":7,"origin":"template"},{"id":"c-AAP-1.D.8","parentId":"c-AAP-1.D","code":"AAP-1.D.8","text":"The exam reference sheet describes a list structure whose index values are 1 through the number of elements in the list, inclusive. For all list operations, if a list index is less than 1 or greater than the length of the list, an error message is produced and the program will terminate.","order":8,"origin":"template"},{"id":"c-AAP-2.A","parentId":"c-3.3","code":"AAP-2.A","text":"Express an algorithm that uses sequencing without using a programming language.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["2.A"]}},{"id":"c-AAP-2.A.1","parentId":"c-AAP-2.A","code":"AAP-2.A.1","text":"An algorithm is a finite set of instructions that accomplish a specific task.","order":1,"origin":"template"},{"id":"c-AAP-2.A.2","parentId":"c-AAP-2.A","code":"AAP-2.A.2","text":"Beyond visual and textual programming languages, algorithms can be expressed in a variety of ways, such as natural language, diagrams, and pseudocode.","order":2,"origin":"template"},{"id":"c-AAP-2.A.3","parentId":"c-AAP-2.A","code":"AAP-2.A.3","text":"Algorithms executed by programs are implemented using programming languages.","order":3,"origin":"template"},{"id":"c-AAP-2.A.4","parentId":"c-AAP-2.A","code":"AAP-2.A.4","text":"Every algorithm can be constructed using combinations of sequencing, selection, and iteration.","order":4,"origin":"template"},{"id":"c-AAP-2.B","parentId":"c-3.3","code":"AAP-2.B","text":"Represent a step-by-step algorithmic process using sequential code statements.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values."}},{"id":"c-AAP-2.B.1","parentId":"c-AAP-2.B","code":"AAP-2.B.1","text":"Sequencing is the application of each step of an algorithm in the order in which the code statements are given.","order":1,"origin":"template"},{"id":"c-AAP-2.B.2","parentId":"c-AAP-2.B","code":"AAP-2.B.2","text":"A code statement is a part of program code that expresses an action to be carried out.","order":2,"origin":"template"},{"id":"c-AAP-2.B.3","parentId":"c-AAP-2.B","code":"AAP-2.B.3","text":"An expression can consist of a value, a variable, an operator, or a procedure call that returns a value.","order":3,"origin":"template"},{"id":"c-AAP-2.B.4","parentId":"c-AAP-2.B","code":"AAP-2.B.4","text":"Expressions are evaluated to produce a single value.","order":4,"origin":"template"},{"id":"c-AAP-2.B.5","parentId":"c-AAP-2.B","code":"AAP-2.B.5","text":"The evaluation of expressions follows a set order of operations defined by the programming language.","order":5,"origin":"template"},{"id":"c-AAP-2.B.6","parentId":"c-AAP-2.B","code":"AAP-2.B.6","text":"Sequential statements execute in the order they appear in the code segment.","order":6,"origin":"template"},{"id":"c-AAP-2.B.7","parentId":"c-AAP-2.B","code":"AAP-2.B.7","text":"Clarity and readability are important considerations when expressing an algorithm in a programming language.","order":7,"origin":"template"},{"id":"c-AAP-2.C","parentId":"c-3.3","code":"AAP-2.C","text":"Evaluate expressions that use arithmetic operators.","order":3,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["4.B"]}},{"id":"c-AAP-2.C.1","parentId":"c-AAP-2.C","code":"AAP-2.C.1","text":"Arithmetic operators are part of most programming languages and include addition, subtraction, multiplication, division, and modulus operators.","order":1,"origin":"template"},{"id":"c-AAP-2.C.2","parentId":"c-AAP-2.C","code":"AAP-2.C.2","text":"The exam reference sheet provides a MOD b, which evaluates to the remainder when a is divided by b. Assume that a is an integer greater than or equal to 0 and b is an integer greater than 0. For example, 17 MOD 5 evaluates to 2.","order":2,"origin":"template"},{"id":"c-AAP-2.C.3","parentId":"c-AAP-2.C","code":"AAP-2.C.3","text":"The exam reference sheet provides the arithmetic operators +, -, *, /, and MOD. Text and Block:","order":3,"origin":"template"},{"id":"c-AAP-2.C.4","parentId":"c-AAP-2.C","code":"AAP-2.C.4","text":"The order of operations used in mathematics applies when evaluating expressions. The MOD operator has the same precedence as the * and / operators.","order":4,"origin":"template"},{"id":"c-AAP-2.D","parentId":"c-3.4","code":"AAP-2.D","text":"Evaluate expressions that manipulate strings.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["4.B"]}},{"id":"c-AAP-2.D.1","parentId":"c-AAP-2.D","code":"AAP-2.D.1","text":"String concatenation joins together two or more strings end-to-end to make a new string.","order":1,"origin":"template"},{"id":"c-AAP-2.D.2","parentId":"c-AAP-2.D","code":"AAP-2.D.2","text":"A substring is part of an existing string.","order":2,"origin":"template"},{"id":"c-AAP-2.E","parentId":"c-3.5","code":"AAP-2.E","text":"For relationships between two variables, expressions, or values: a. Write expressions using relational operators. 2.B b. Evaluate expressions that use relational operators.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["4.B"]}},{"id":"c-AAP-2.E.1","parentId":"c-AAP-2.E","code":"AAP-2.E.1","text":"A Boolean value is either true or false.","order":1,"origin":"template"},{"id":"c-AAP-2.E.2","parentId":"c-AAP-2.E","code":"AAP-2.E.2","text":"The exam reference sheet provides the following relational operators: =, ≠, >, <, ≥, and ≤. Text and Block:","order":2,"origin":"template"},{"id":"c-AAP-2.F","parentId":"c-3.5","code":"AAP-2.F","text":"For relationships between Boolean values: a. Write expressions using logical operators. 2.B b. Evaluate expressions that use logic operators.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["4.B"]}},{"id":"c-AAP-2.F.1","parentId":"c-AAP-2.F","code":"AAP-2.F.1","text":"The exam reference sheet provides the logical operators NOT, AND, and OR, which evaluate to a Boolean value.","order":1,"origin":"template"},{"id":"c-AAP-2.F.2","parentId":"c-AAP-2.F","code":"AAP-2.F.2","text":"The exam reference sheet provides Text: NOT condition Block: NOT condition which evaluates to true if condition is false; otherwise it evaluates to false.","order":2,"origin":"template"},{"id":"c-AAP-2.F.3","parentId":"c-AAP-2.F","code":"AAP-2.F.3","text":"The exam reference sheet provides Text: condition1 AND condition2 Block: condition1 AND condition2 which evaluates to true if both condition1 and condition2 are true; otherwise it evaluates to false.","order":3,"origin":"template"},{"id":"c-AAP-2.F.4","parentId":"c-AAP-2.F","code":"AAP-2.F.4","text":"The exam reference sheet provides Text: condition1 OR condition2 Block: condition1 OR condition2 which evaluates to true if condition1 is true or if condition2 is true or if both condition1 and condition2 are true; otherwise it evaluates to false.","order":4,"origin":"template"},{"id":"c-AAP-2.F.5","parentId":"c-AAP-2.F","code":"AAP-2.F.5","text":"The operand for a logical operator is either a Boolean expression or a single Boolean value.","order":5,"origin":"template"},{"id":"c-AAP-2.G","parentId":"c-3.6","code":"AAP-2.G","text":"Express an algorithm that uses selection without using a programming language.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["2.A"]}},{"id":"c-AAP-2.G.1","parentId":"c-AAP-2.G","code":"AAP-2.G.1","text":"Selection determines which parts of an algorithm are executed based on a condition being true or false.","order":1,"origin":"template"},{"id":"c-AAP-2.H","parentId":"c-3.6","code":"AAP-2.H","text":"For selection: a. Write conditional statements. 2.B b. Determine the result of conditional statements.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["4.B"]}},{"id":"c-AAP-2.H.1","parentId":"c-AAP-2.H","code":"AAP-2.H.1","text":"Conditional statements, or “if-statements,” affect the sequential flow of control by executing different statements based on the value of a Boolean expression.","order":1,"origin":"template"},{"id":"c-AAP-2.H.2","parentId":"c-AAP-2.H","code":"AAP-2.H.2","text":"The exam reference sheet provides Text: IF(condition) { <block of statements> } Block: IF condition block of statements","order":2,"origin":"template"},{"id":"c-AAP-2.H.3","parentId":"c-AAP-2.H","code":"AAP-2.H.3","text":"The exam reference sheet provides Text: IF(condition) { <first block of statements> } ELSE { <second block of statements> } Block: IF condition first block of statements ELSE second block of statements in which the code in first block of statements is executed if the Boolean expression condition evaluates to true; otherwise, the code in second block of statements is executed.","order":3,"origin":"template"},{"id":"c-AAP-2.I","parentId":"c-3.7","code":"AAP-2.I","text":"For nested selection: a. Write nested conditional statements. 2.B b. Determine the result of nested conditional statements.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["4.B"]}},{"id":"c-AAP-2.I.1","parentId":"c-AAP-2.I","code":"AAP-2.I.1","text":"Nested conditional statements consist of conditional statements within conditional statements.","order":1,"origin":"template"},{"id":"c-AAP-2.J","parentId":"c-3.8","code":"AAP-2.J","text":"Express an algorithm that uses iteration without using a programming language.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["2.A"]}},{"id":"c-AAP-2.J.1","parentId":"c-AAP-2.J","code":"AAP-2.J.1","text":"Iteration is a repeating portion of an algorithm. Iteration repeats a specified number of times or until a given condition is met.","order":1,"origin":"template"},{"id":"c-AAP-2.K","parentId":"c-3.8","code":"AAP-2.K","text":"For iteration: a. Write iteration statements.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values."}},{"id":"c-AAP-2.K.1","parentId":"c-AAP-2.K","code":"AAP-2.K.1","text":"Iteration statements change the sequential flow of control by repeating a set of statements zero or more times, until a stopping condition is met.","order":1,"origin":"template"},{"id":"c-AAP-2.K.2","parentId":"c-AAP-2.K","code":"AAP-2.K.2","text":"The exam reference sheet provides Text: REPEAT n TIMES { <block of statements> } Block: REPEAT n TIMES block of statements in which the block of statements is executed n times.","order":2,"origin":"template"},{"id":"c-AAP-2.K.3","parentId":"c-AAP-2.K","code":"AAP-2.K.3","text":"The exam reference sheet provides Text: REPEAT UNTIL(condition) { <block of statements> } Block: REPEAT UNTIL condition block of statements in which the code in block of statements is repeated until the Boolean expression condition evaluates to true.","order":3,"origin":"template"},{"id":"c-AAP-2.K.4","parentId":"c-AAP-2.K","code":"AAP-2.K.4","text":"In REPEAT UNTIL(condition) iteration, an infinite loop occurs when the ending condition will never evaluate to true.","order":4,"origin":"template"},{"id":"c-AAP-2.K.5","parentId":"c-AAP-2.K","code":"AAP-2.K.5","text":"In REPEAT UNTIL(condition) iteration, if the conditional evaluates to true initially, the loop body is not executed at all, due to the condition being checked before the loop.","order":5,"origin":"template"},{"id":"c-AAP-2.L","parentId":"c-3.9","code":"AAP-2.L","text":"Compare multiple algorithms to determine if they yield the same side effect or result.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["1.D"]}},{"id":"c-AAP-2.L.1","parentId":"c-AAP-2.L","code":"AAP-2.L.1","text":"Algorithms can be written in different ways and still accomplish the same tasks.","order":1,"origin":"template"},{"id":"c-AAP-2.L.2","parentId":"c-AAP-2.L","code":"AAP-2.L.2","text":"Algorithms that appear similar can yield different side effects or results.","order":2,"origin":"template"},{"id":"c-AAP-2.L.3","parentId":"c-AAP-2.L","code":"AAP-2.L.3","text":"Some conditional statements can be written as equivalent Boolean expressions.","order":3,"origin":"template"},{"id":"c-AAP-2.L.4","parentId":"c-AAP-2.L","code":"AAP-2.L.4","text":"Some Boolean expressions can be written as equivalent conditional statements.","order":4,"origin":"template"},{"id":"c-AAP-2.L.5","parentId":"c-AAP-2.L","code":"AAP-2.L.5","text":"Different algorithms can be developed or used to solve the same problem.","order":5,"origin":"template"},{"id":"c-AAP-2.M","parentId":"c-3.9","code":"AAP-2.M","text":"For algorithms: a. Create algorithms. 2.A b. Combine and modify existing algorithms.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["2.B"]}},{"id":"c-AAP-2.M.1","parentId":"c-AAP-2.M","code":"AAP-2.M.1","text":"Algorithms can be created from an idea, by combining existing algorithms, or by modifying existing algorithms.","order":1,"origin":"template"},{"id":"c-AAP-2.M.2","parentId":"c-AAP-2.M","code":"AAP-2.M.2","text":"Knowledge of existing algorithms can help in constructing new ones. Some existing algorithms include:","order":2,"origin":"template"},{"id":"c-AAP-2.M.3","parentId":"c-AAP-2.M","code":"AAP-2.M.3","text":"Using existing correct algorithms as building blocks for constructing another algorithm has benefits such as reducing development time, reducing testing, and simplifying the identification of errors.","order":3,"origin":"template"},{"id":"c-AAP-2.N","parentId":"c-3.10","code":"AAP-2.N","text":"For list operations: a. Write expressions that use list indexing and list procedures. 2.B b. Evaluate expressions that use list indexing and list procedures.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["4.B"]}},{"id":"c-AAP-2.N.1","parentId":"c-AAP-2.N","code":"AAP-2.N.1","text":"The exam reference sheet provides basic operations on lists, including:","order":1,"origin":"template"},{"id":"c-AAP-2.N.2","parentId":"c-AAP-2.N","code":"AAP-2.N.2","text":"List procedures are implemented in accordance with the syntax rules of the programming language.","order":2,"origin":"template"},{"id":"c-AAP-2.O","parentId":"c-3.10","code":"AAP-2.O","text":"For algorithms involving elements of a list: a. Write iteration statements to traverse a list. 2.B b. Determine the result of an algorithm that includes list traversals.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["4.B"]}},{"id":"c-AAP-2.O.1","parentId":"c-AAP-2.O","code":"AAP-2.O.1","text":"Traversing a list can be a complete traversal, where all elements in the list are accessed, or a partial traversal, where only a portion of elements are accessed. [Exclusion statement: EK AAP-2.O.1): Traversing multiple lists at the same time using the same index for both (parallel traversals) is outside the scope of this course and the AP Exam.]","order":1,"origin":"template","meta":{"exclusion":"EK AAP-2.O.1): Traversing multiple lists at the same time using the same index for both (parallel traversals) is outside the scope of this course and the AP Exam."}},{"id":"c-AAP-2.O.2","parentId":"c-AAP-2.O","code":"AAP-2.O.2","text":"Iteration statements can be used to traverse a list.","order":2,"origin":"template"},{"id":"c-AAP-2.O.3","parentId":"c-AAP-2.O","code":"AAP-2.O.3","text":"The exam reference sheet provides Text: FOR EACH item IN aList { <block of statements> } Block: FOR EACH item IN aList block of statements The variable item is assigned the value of each element of aList sequentially, in order, from the first element to the last element. The code in block of statements is executed once for each assignment of item.","order":3,"origin":"template"},{"id":"c-AAP-2.O.4","parentId":"c-AAP-2.O","code":"AAP-2.O.4","text":"Knowledge of existing algorithms that use iteration can help in constructing new algorithms. Some examples of existing algorithms that are often used with lists include:","order":4,"origin":"template"},{"id":"c-AAP-2.O.5","parentId":"c-AAP-2.O","code":"AAP-2.O.5","text":"Linear search or sequential search algorithms check each element of a list, in order, until the desired value is found or all elements in the list have been checked.","order":5,"origin":"template"},{"id":"c-AAP-2.P","parentId":"c-3.11","code":"AAP-2.P","text":"For binary search algorithms: a. Determine the number of iterations required to find a value in a data set. 1.D b. Explain the requirements necessary to complete a binary search.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-2: The way statements are sequenced and combined in a program determines the computed result. Programs incorporate iteration and selection constructs to represent repetition and make decisions to handle varied input values.","skills":["1.A"]}},{"id":"c-AAP-2.P.1","parentId":"c-AAP-2.P","code":"AAP-2.P.1","text":"The binary search algorithm starts at the middle of a sorted data set of numbers and eliminates half of the data; this process repeats until the desired value is found or all elements have been eliminated. [Exclusion statement: EK: AAP-2.P.1): Specific implementations of the binary search are outside the scope of the course and the AP Exam.]","order":1,"origin":"template","meta":{"exclusion":"EK: AAP-2.P.1): Specific implementations of the binary search are outside the scope of the course and the AP Exam."}},{"id":"c-AAP-2.P.2","parentId":"c-AAP-2.P","code":"AAP-2.P.2","text":"Data must be in sorted order to use the binary search algorithm.","order":2,"origin":"template"},{"id":"c-AAP-2.P.3","parentId":"c-AAP-2.P","code":"AAP-2.P.3","text":"Binary search is often more efficient than sequential/linear search when applied to sorted data.","order":3,"origin":"template"},{"id":"c-AAP-3.A","parentId":"c-3.12","code":"AAP-3.A","text":"For procedure calls: a. Write statements to call procedures. 3.B b. Determine the result or effect of a procedure call.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-3: Programmers break down problems into smaller and more manageable pieces. By creating procedures and leveraging parameters, programmers generalize processes that can be reused. Procedures allow programmers to draw upon existing code that has already been tested, allowing them to write programs more quickly and with more confidence."}},{"id":"c-AAP-3.A.1","parentId":"c-AAP-3.A","code":"AAP-3.A.1","text":"A procedure is a named group of programming instructions that may have parameters and","order":1,"origin":"template"},{"id":"c-AAP-3.A.2","parentId":"c-AAP-3.A","code":"AAP-3.A.2","text":"Procedures are referred to by different names, such as method or function, depending on the programming language.","order":2,"origin":"template"},{"id":"c-AAP-3.A.3","parentId":"c-AAP-3.A","code":"AAP-3.A.3","text":"Parameters are input variables of a procedure. Arguments specify the values of the parameters when a procedure is called.","order":3,"origin":"template"},{"id":"c-AAP-3.A.4","parentId":"c-AAP-3.A","code":"AAP-3.A.4","text":"A procedure call interrupts the sequential execution of statements, causing the program to execute the statements within the procedure before continuing. Once the last statement in the procedure (or a return statement) has executed, flow of control is returned to the point immediately following where the procedure was called.","order":4,"origin":"template"},{"id":"c-AAP-3.A.5","parentId":"c-AAP-3.A","code":"AAP-3.A.5","text":"The exam reference sheet provides procName(arg1, arg2,...)","order":5,"origin":"template"},{"id":"c-AAP-3.A.6","parentId":"c-AAP-3.A","code":"AAP-3.A.6","text":"The exam reference sheet provides the procedure Text: DISPLAY(expression) Block: DISPLAY expression to display the value of expression, followed by a space.","order":6,"origin":"template"},{"id":"c-AAP-3.A.7","parentId":"c-AAP-3.A","code":"AAP-3.A.7","text":"The exam reference sheet provides the Text:","order":7,"origin":"template"},{"id":"c-AAP-3.A.8","parentId":"c-AAP-3.A","code":"AAP-3.A.8","text":"The exam reference sheet provides result procName(arg1, arg2,...) to assign to result the “value of the procedure” being returned by calling","order":8,"origin":"template"},{"id":"c-AAP-3.A.9","parentId":"c-AAP-3.A","code":"AAP-3.A.9","text":"The exam reference sheet provides procedure Text: INPUT() Block: INPUT which accepts a value from the user and","order":9,"origin":"template"},{"id":"c-AAP-3.B","parentId":"c-3.13","code":"AAP-3.B","text":"Explain how the use of procedural abstraction manages complexity in a program.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-3: Programmers break down problems into smaller and more manageable pieces. By creating procedures and leveraging parameters, programmers generalize processes that can be reused. Procedures allow programmers to draw upon existing code that has already been tested, allowing them to write programs more quickly and with more confidence.","skills":["3.C"]}},{"id":"c-AAP-3.B.1","parentId":"c-AAP-3.B","code":"AAP-3.B.1","text":"One common type of abstraction is procedural abstraction, which provides a name for a process and allows a procedure to be used only knowing what it does, not how it does it.","order":1,"origin":"template"},{"id":"c-AAP-3.B.2","parentId":"c-AAP-3.B","code":"AAP-3.B.2","text":"Procedural abstraction allows a solution to a large problem to be based on the solutions of smaller subproblems. This is accomplished by creating procedures to solve each of the subproblems.","order":2,"origin":"template"},{"id":"c-AAP-3.B.3","parentId":"c-AAP-3.B","code":"AAP-3.B.3","text":"The subdivision of a computer program into separate subprograms is called modularity.","order":3,"origin":"template"},{"id":"c-AAP-3.B.4","parentId":"c-AAP-3.B","code":"AAP-3.B.4","text":"A procedural abstraction may extract shared features to generalize functionality instead of duplicating code. This allows for program code reuse, which helps manage complexity.","order":4,"origin":"template"},{"id":"c-AAP-3.B.5","parentId":"c-AAP-3.B","code":"AAP-3.B.5","text":"Using parameters allows procedures to be generalized, enabling the procedures to be reused with a range of input values or arguments.","order":5,"origin":"template"},{"id":"c-AAP-3.B.6","parentId":"c-AAP-3.B","code":"AAP-3.B.6","text":"Using procedural abstraction helps improve code readability.","order":6,"origin":"template"},{"id":"c-AAP-3.B.7","parentId":"c-AAP-3.B","code":"AAP-3.B.7","text":"Using procedural abstraction in a program allows programmers to change the internals of the procedure (to make it faster, more efficient, use less storage, etc.) without needing to notify users of the change as long as what the procedure does is preserved.","order":7,"origin":"template"},{"id":"c-AAP-3.C","parentId":"c-3.13","code":"AAP-3.C","text":"Develop procedural abstractions to manage complexity in a program by writing procedures.","order":2,"origin":"template","meta":{"enduringUnderstanding":"AAP-3: Programmers break down problems into smaller and more manageable pieces. By creating procedures and leveraging parameters, programmers generalize processes that can be reused. Procedures allow programmers to draw upon existing code that has already been tested, allowing them to write programs more quickly and with more confidence.","skills":["3.B"]}},{"id":"c-AAP-3.C.1","parentId":"c-AAP-3.C","code":"AAP-3.C.1","text":"The exam reference sheet provides Text: PROCEDURE procName(parameter1, parameter2,...) { <block of statements> } Block: PROCEDURE procName parameter1, parameter2,... block of statements which is used to define a procedure that takes zero or more arguments. The procedure contains block of statements.","order":1,"origin":"template"},{"id":"c-AAP-3.C.2","parentId":"c-AAP-3.C","code":"AAP-3.C.2","text":"The exam reference sheet provides Text: PROCEDURE procName(parameter1, parameter2,...) { <block of statements>","order":2,"origin":"template"},{"id":"c-AAP-3.D","parentId":"c-3.14","code":"AAP-3.D","text":"Select appropriate libraries or existing code segments to use in creating new programs.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-3: Programmers break down problems into smaller and more manageable pieces. By creating procedures and leveraging parameters, programmers generalize processes that can be reused. Procedures allow programmers to draw upon existing code that has already been tested, allowing them to write programs more quickly and with more confidence.","skills":["2.B"]}},{"id":"c-AAP-3.D.1","parentId":"c-AAP-3.D","code":"AAP-3.D.1","text":"A software library contains procedures that may be used in creating new programs.","order":1,"origin":"template"},{"id":"c-AAP-3.D.2","parentId":"c-AAP-3.D","code":"AAP-3.D.2","text":"Existing code segments can come from internal or external sources, such as libraries or previously written code.","order":2,"origin":"template"},{"id":"c-AAP-3.D.3","parentId":"c-AAP-3.D","code":"AAP-3.D.3","text":"The use of libraries simplifies the task of creating complex programs.","order":3,"origin":"template"},{"id":"c-AAP-3.D.4","parentId":"c-AAP-3.D","code":"AAP-3.D.4","text":"Application program interfaces (APIs) are specifications for how the procedures in a library behave and can be used.","order":4,"origin":"template"},{"id":"c-AAP-3.D.5","parentId":"c-AAP-3.D","code":"AAP-3.D.5","text":"Documentation for an API/library is necessary in understanding the behaviors provided by the API/library and how to use them.","order":5,"origin":"template"},{"id":"c-AAP-3.E","parentId":"c-3.15","code":"AAP-3.E","text":"For generating random values: a. Write expressions to generate possible values.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-3: Programmers break down problems into smaller and more manageable pieces. By creating procedures and leveraging parameters, programmers generalize processes that can be reused. Procedures allow programmers to draw upon existing code that has already been tested, allowing them to write programs more quickly and with more confidence."}},{"id":"c-AAP-3.E.1","parentId":"c-AAP-3.E","code":"AAP-3.E.1","text":"The exam reference sheet provides Text: RANDOM(a, b) Block: RANDOM a, b which generates and returns a random integer from a to b, inclusive. Each result is equally likely to occur. For example, RANDOM(1, 3) could return 1, 2, or 3.","order":1,"origin":"template"},{"id":"c-AAP-3.E.2","parentId":"c-AAP-3.E","code":"AAP-3.E.2","text":"Using random number generation in a program means each execution may produce a different result.","order":2,"origin":"template"},{"id":"c-AAP-3.F","parentId":"c-3.16","code":"AAP-3.F","text":"For simulations: a. Explain how computers can be used to represent real-world phenomena or outcomes. 1.A b. Compare simulations with real-world contexts.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-3: Programmers break down problems into smaller and more manageable pieces. By creating procedures and leveraging parameters, programmers generalize processes that can be reused. Procedures allow programmers to draw upon existing code that has already been tested, allowing them to write programs more quickly and with more confidence.","skills":["1.D"]}},{"id":"c-AAP-3.F.1","parentId":"c-AAP-3.F","code":"AAP-3.F.1","text":"Simulations are abstractions of more complex objects or phenomena for a specific purpose.","order":1,"origin":"template"},{"id":"c-AAP-3.F.2","parentId":"c-AAP-3.F","code":"AAP-3.F.2","text":"A simulation is a representation that uses varying sets of values to reflect the changing state of a phenomenon.","order":2,"origin":"template"},{"id":"c-AAP-3.F.3","parentId":"c-AAP-3.F","code":"AAP-3.F.3","text":"Simulations often mimic real-world events with the purpose of drawing inferences, allowing investigation of a phenomenon without the constraints of the real world.","order":3,"origin":"template"},{"id":"c-AAP-3.F.4","parentId":"c-AAP-3.F","code":"AAP-3.F.4","text":"The process of developing an abstract simulation involves removing specific details or simplifying functionality.","order":4,"origin":"template"},{"id":"c-AAP-3.F.5","parentId":"c-AAP-3.F","code":"AAP-3.F.5","text":"Simulations can contain bias derived from the choices of real-world elements that were included or excluded.","order":5,"origin":"template"},{"id":"c-AAP-3.F.6","parentId":"c-AAP-3.F","code":"AAP-3.F.6","text":"Simulations are most useful when real-world events are impractical for experiments (e.g., too big, too small, too fast, too slow, too expensive, or too dangerous).","order":6,"origin":"template"},{"id":"c-AAP-3.F.7","parentId":"c-AAP-3.F","code":"AAP-3.F.7","text":"Simulations facilitate the formulation and refinement of hypotheses related to the objects or phenomena under consideration.","order":7,"origin":"template"},{"id":"c-AAP-3.F.8","parentId":"c-AAP-3.F","code":"AAP-3.F.8","text":"Random number generators can be used to simulate the variability that exists in the real world.","order":8,"origin":"template"},{"id":"c-AAP-4.A","parentId":"c-3.17","code":"AAP-4.A","text":"For determining the efficiency of an algorithm: a. Explain the difference between algorithms that run in reasonable time and those that do not. 1.D b. Identify situations where a heuristic solution may be more appropriate.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-4: There exist problems that computers cannot solve, and even when a computer can solve a problem, it may not be able to do so in a reasonable amount of time.","skills":["1.D"]}},{"id":"c-AAP-4.A.1","parentId":"c-AAP-4.A","code":"AAP-4.A.1","text":"A problem is a general description of a task that can (or cannot) be solved algorithmically. An instance of a problem also includes specific input. For example, sorting is a problem; sorting the list (2,3,1,7) is an instance of the problem.","order":1,"origin":"template"},{"id":"c-AAP-4.A.2","parentId":"c-AAP-4.A","code":"AAP-4.A.2","text":"A decision problem is a problem with a yes/no answer (e.g., is there a path from A to B?). An optimization problem is a problem with the goal of finding the “best” solution among many (e.g., what is the shortest path from A to B?).","order":2,"origin":"template"},{"id":"c-AAP-4.A.3","parentId":"c-AAP-4.A","code":"AAP-4.A.3","text":"Efficiency is an estimation of the amount of computational resources used by an algorithm. Efficiency is typically expressed as a function of the size of the input. [Exclusion statement: EK AAP-4.A.3): Formal analysis of algorithms (Big-O) and formal reasoning using mathematical formulas are outside the scope of this course and the AP Exam.]","order":3,"origin":"template","meta":{"exclusion":"EK AAP-4.A.3): Formal analysis of algorithms (Big-O) and formal reasoning using mathematical formulas are outside the scope of this course and the AP Exam."}},{"id":"c-AAP-4.A.4","parentId":"c-AAP-4.A","code":"AAP-4.A.4","text":"An algorithm’s efficiency is determined through formal or mathematical reasoning.","order":4,"origin":"template"},{"id":"c-AAP-4.A.5","parentId":"c-AAP-4.A","code":"AAP-4.A.5","text":"An algorithm’s efficiency can be informally measured by determining the number of times a statement or group of statements executes.","order":5,"origin":"template"},{"id":"c-AAP-4.A.6","parentId":"c-AAP-4.A","code":"AAP-4.A.6","text":"Different correct algorithms for the same problem can have different efficiencies.","order":6,"origin":"template"},{"id":"c-AAP-4.A.7","parentId":"c-AAP-4.A","code":"AAP-4.A.7","text":"Algorithms with a polynomial efficiency or slower (constant, linear, square, cube, etc.) are said to run in a reasonable amount of time. Algorithms with exponential or factorial efficiencies are examples of algorithms that run in an unreasonable amount of time.","order":7,"origin":"template"},{"id":"c-AAP-4.A.8","parentId":"c-AAP-4.A","code":"AAP-4.A.8","text":"Some problems cannot be solved in a reasonable amount of time because there is no efficient algorithm for solving them. In these cases, approximate solutions are sought.","order":8,"origin":"template"},{"id":"c-AAP-4.A.9","parentId":"c-AAP-4.A","code":"AAP-4.A.9","text":"A heuristic is an approach to a problem that produces a solution that is not guaranteed to be optimal but may be used when techniques that are guaranteed to always find an optimal solution are impractical. [Exclusion statement: AAP-4.A.9): Specific heuristic solutions are outside the scope of this course and the AP Exam.]","order":9,"origin":"template","meta":{"exclusion":"AAP-4.A.9): Specific heuristic solutions are outside the scope of this course and the AP Exam."}},{"id":"c-AAP-4.B","parentId":"c-3.18","code":"AAP-4.B","text":"Explain the existence of undecidable problems in computer science.","order":1,"origin":"template","meta":{"enduringUnderstanding":"AAP-4: There exist problems that computers cannot solve, and even when a computer can solve a problem, it may not be able to do so in a reasonable amount of time.","skills":["1.A"]}},{"id":"c-AAP-4.B.1","parentId":"c-AAP-4.B","code":"AAP-4.B.1","text":"A decidable problem is a decision problem for which an algorithm can be written to produce a correct output for all inputs (e.g., “Is the number even?”).","order":1,"origin":"template"},{"id":"c-AAP-4.B.2","parentId":"c-AAP-4.B","code":"AAP-4.B.2","text":"An undecidable problem is one for which no algorithm can be constructed that is always capable of providing a correct yes-or-no answer. [Exclusion statement: EK AAP-4.B.2): Determining whether a given problem is undecidable is outside the scope of this course and the AP Exam.]","order":2,"origin":"template","meta":{"exclusion":"EK AAP-4.B.2): Determining whether a given problem is undecidable is outside the scope of this course and the AP Exam."}},{"id":"c-AAP-4.B.3","parentId":"c-AAP-4.B","code":"AAP-4.B.3","text":"An undecidable problem may have some instances that have an algorithmic solution, but there is no algorithmic solution that could solve all instances of the problem.","order":3,"origin":"template"},{"id":"c-CSN-1.A","parentId":"c-4.1","code":"CSN-1.A","text":"Explain how computing devices work together in a network.","order":1,"origin":"template","meta":{"enduringUnderstanding":"CSN-1: Computer systems and networks facilitate the transfer of data.","skills":["5.A"]}},{"id":"c-CSN-1.A.1","parentId":"c-CSN-1.A","code":"CSN-1.A.1","text":"A computing device is a physical artifact that can run a program. Some examples include computers, tablets, servers, routers, and smart sensors.","order":1,"origin":"template"},{"id":"c-CSN-1.A.2","parentId":"c-CSN-1.A","code":"CSN-1.A.2","text":"A computing system is a group of computing devices and programs working together for a common purpose.","order":2,"origin":"template"},{"id":"c-CSN-1.A.3","parentId":"c-CSN-1.A","code":"CSN-1.A.3","text":"A computer network is a group of interconnected computing devices capable of sending or receiving data.","order":3,"origin":"template"},{"id":"c-CSN-1.A.4","parentId":"c-CSN-1.A","code":"CSN-1.A.4","text":"A computer network is a type of computing system.","order":4,"origin":"template"},{"id":"c-CSN-1.A.5","parentId":"c-CSN-1.A","code":"CSN-1.A.5","text":"A path between two computing devices on a computer network (a sender and a receiver) is a sequence of directly connected computing devices that begins at the sender and ends at the receiver.","order":5,"origin":"template"},{"id":"c-CSN-1.A.6","parentId":"c-CSN-1.A","code":"CSN-1.A.6","text":"Routing is the process of finding a path from sender to receiver.","order":6,"origin":"template"},{"id":"c-CSN-1.A.7","parentId":"c-CSN-1.A","code":"CSN-1.A.7","text":"The bandwidth of a computer network is the maximum amount of data that can be sent in a fixed amount of time.","order":7,"origin":"template"},{"id":"c-CSN-1.A.8","parentId":"c-CSN-1.A","code":"CSN-1.A.8","text":"Bandwidth is usually measured in bits per second.","order":8,"origin":"template"},{"id":"c-CSN-1.B","parentId":"c-4.1","code":"CSN-1.B","text":"Explain how the Internet works.","order":2,"origin":"template","meta":{"enduringUnderstanding":"CSN-1: Computer systems and networks facilitate the transfer of data.","skills":["5.A"]}},{"id":"c-CSN-1.B.1","parentId":"c-CSN-1.B","code":"CSN-1.B.1","text":"The Internet is a computer network consisting of interconnected networks that use standardized, open (nonproprietary) communication protocols.","order":1,"origin":"template"},{"id":"c-CSN-1.B.2","parentId":"c-CSN-1.B","code":"CSN-1.B.2","text":"Access to the Internet depends on the ability to connect a computing device to an Internet-connected device.","order":2,"origin":"template"},{"id":"c-CSN-1.B.3","parentId":"c-CSN-1.B","code":"CSN-1.B.3","text":"A protocol is an agreed-upon set of rules that specify the behavior of a system.","order":3,"origin":"template"},{"id":"c-CSN-1.B.4","parentId":"c-CSN-1.B","code":"CSN-1.B.4","text":"The protocols used in the Internet are open, which allows users to easily connect additional computing devices to the Internet.","order":4,"origin":"template"},{"id":"c-CSN-1.B.5","parentId":"c-CSN-1.B","code":"CSN-1.B.5","text":"Routing on the Internet is usually dynamic; it is not specified in advance.","order":5,"origin":"template"},{"id":"c-CSN-1.B.6","parentId":"c-CSN-1.B","code":"CSN-1.B.6","text":"The scalability of a system is the capacity for the system to change in size and scale to meet new demands.","order":6,"origin":"template"},{"id":"c-CSN-1.B.7","parentId":"c-CSN-1.B","code":"CSN-1.B.7","text":"The Internet was designed to be scalable.","order":7,"origin":"template"},{"id":"c-CSN-1.C","parentId":"c-4.1","code":"CSN-1.C","text":"Explain how data are sent through the Internet via packets.","order":3,"origin":"template","meta":{"enduringUnderstanding":"CSN-1: Computer systems and networks facilitate the transfer of data.","skills":["5.A"]}},{"id":"c-CSN-1.C.1","parentId":"c-CSN-1.C","code":"CSN-1.C.1","text":"Information is passed through the Internet as a data stream. Data streams contain chunks of data, which are encapsulated in packets.","order":1,"origin":"template"},{"id":"c-CSN-1.C.2","parentId":"c-CSN-1.C","code":"CSN-1.C.2","text":"Packets contain a chunk of data and metadata used for routing the packet between the origin and the destination on the Internet, as well as for data reassembly.","order":2,"origin":"template"},{"id":"c-CSN-1.C.3","parentId":"c-CSN-1.C","code":"CSN-1.C.3","text":"Packets may arrive at the destination in order, out of order, or not at all.","order":3,"origin":"template"},{"id":"c-CSN-1.C.4","parentId":"c-CSN-1.C","code":"CSN-1.C.4","text":"IP, TCP, and UDP are common protocols used on the Internet.","order":4,"origin":"template"},{"id":"c-CSN-1.D","parentId":"c-4.1","code":"CSN-1.D","text":"Describe the differences between the Internet and the World Wide Web.","order":4,"origin":"template","meta":{"enduringUnderstanding":"CSN-1: Computer systems and networks facilitate the transfer of data.","skills":["5.A"]}},{"id":"c-CSN-1.D.1","parentId":"c-CSN-1.D","code":"CSN-1.D.1","text":"The World Wide Web is a system of linked pages, programs, and files.","order":1,"origin":"template"},{"id":"c-CSN-1.D.2","parentId":"c-CSN-1.D","code":"CSN-1.D.2","text":"HTTP is a protocol used by the World Wide Web.","order":2,"origin":"template"},{"id":"c-CSN-1.D.3","parentId":"c-CSN-1.D","code":"CSN-1.D.3","text":"The World Wide Web uses the Internet.","order":3,"origin":"template"},{"id":"c-CSN-1.E","parentId":"c-4.2","code":"CSN-1.E","text":"For fault-tolerant systems, like the Internet: a. Describe the benefits of fault tolerance. 1.D b. Explain how a given system is fault-tolerant. 5.A c. Identify vulnerabilities to failure in a system.","order":1,"origin":"template","meta":{"enduringUnderstanding":"CSN-1: Computer systems and networks facilitate the transfer of data.","skills":["1.D"]}},{"id":"c-CSN-1.E.1","parentId":"c-CSN-1.E","code":"CSN-1.E.1","text":"The Internet has been engineered to be fault-tolerant, with abstractions for routing and transmitting data.","order":1,"origin":"template"},{"id":"c-CSN-1.E.2","parentId":"c-CSN-1.E","code":"CSN-1.E.2","text":"Redundancy is the inclusion of extra components that can be used to mitigate failure of a system if other components fail.","order":2,"origin":"template"},{"id":"c-CSN-1.E.3","parentId":"c-CSN-1.E","code":"CSN-1.E.3","text":"One way to accomplish network redundancy is by having more than one path between any two connected devices.","order":3,"origin":"template"},{"id":"c-CSN-1.E.4","parentId":"c-CSN-1.E","code":"CSN-1.E.4","text":"If a particular device or connection on the Internet fails, subsequent data will be sent via a different route, if possible.","order":4,"origin":"template"},{"id":"c-CSN-1.E.5","parentId":"c-CSN-1.E","code":"CSN-1.E.5","text":"When a system can support failures and still continue to function, it is called fault-tolerant. This is important because elements of complex systems fail at unexpected times, often in groups, and fault tolerance allows users to continue to use the network.","order":5,"origin":"template"},{"id":"c-CSN-1.E.6","parentId":"c-CSN-1.E","code":"CSN-1.E.6","text":"Redundancy within a system often requires additional resources but can provide the benefit of fault tolerance.","order":6,"origin":"template"},{"id":"c-CSN-1.E.7","parentId":"c-CSN-1.E","code":"CSN-1.E.7","text":"The redundancy of routing options between two points increases the reliability of the Internet and helps it scale to more devices and more people.","order":7,"origin":"template"},{"id":"c-CSN-2.A","parentId":"c-4.3","code":"CSN-2.A","text":"For sequential, parallel, and distributed computing: a. Compare problem solutions. 1.D b. Determine the efficiency of solutions.","order":1,"origin":"template","meta":{"enduringUnderstanding":"CSN-2: Parallel and distributed computing leverage multiple computers to more quickly solve complex problems or process large data sets.","skills":["1.D"]}},{"id":"c-CSN-2.A.1","parentId":"c-CSN-2.A","code":"CSN-2.A.1","text":"Sequential computing is a computational model in which operations are performed in order one at a time.","order":1,"origin":"template"},{"id":"c-CSN-2.A.2","parentId":"c-CSN-2.A","code":"CSN-2.A.2","text":"Parallel computing is a computational model where the program is broken into multiple smaller sequential computing operations, some of which are performed simultaneously.","order":2,"origin":"template"},{"id":"c-CSN-2.A.3","parentId":"c-CSN-2.A","code":"CSN-2.A.3","text":"Distributed computing is a computational model in which multiple devices are used to run a program.","order":3,"origin":"template"},{"id":"c-CSN-2.A.4","parentId":"c-CSN-2.A","code":"CSN-2.A.4","text":"Comparing efficiency of solutions can be done by comparing the time it takes them to perform the same task.","order":4,"origin":"template"},{"id":"c-CSN-2.A.5","parentId":"c-CSN-2.A","code":"CSN-2.A.5","text":"A sequential solution takes as long as the sum of all of its steps.","order":5,"origin":"template"},{"id":"c-CSN-2.A.6","parentId":"c-CSN-2.A","code":"CSN-2.A.6","text":"A parallel computing solution takes as long as its sequential tasks plus the longest of its parallel tasks.","order":6,"origin":"template"},{"id":"c-CSN-2.A.7","parentId":"c-CSN-2.A","code":"CSN-2.A.7","text":"The “speedup” of a parallel solution is measured in the time it took to complete the task sequentially divided by the time it took to complete the task when done in parallel.","order":7,"origin":"template"},{"id":"c-CSN-2.B","parentId":"c-4.3","code":"CSN-2.B","text":"Describe benefits and challenges of parallel and distributed computing.","order":2,"origin":"template","meta":{"enduringUnderstanding":"CSN-2: Parallel and distributed computing leverage multiple computers to more quickly solve complex problems or process large data sets.","skills":["1.D"]}},{"id":"c-CSN-2.B.1","parentId":"c-CSN-2.B","code":"CSN-2.B.1","text":"Parallel computing consists of a parallel portion and a sequential portion.","order":1,"origin":"template"},{"id":"c-CSN-2.B.2","parentId":"c-CSN-2.B","code":"CSN-2.B.2","text":"Solutions that use parallel computing can scale more effectively than solutions that use sequential computing.","order":2,"origin":"template"},{"id":"c-CSN-2.B.3","parentId":"c-CSN-2.B","code":"CSN-2.B.3","text":"Distributed computing allows problems to be solved that could not be solved on a single computer because of either the processing time or storage needs involved.","order":3,"origin":"template"},{"id":"c-CSN-2.B.4","parentId":"c-CSN-2.B","code":"CSN-2.B.4","text":"Distributed computing allows much larger problems to be solved quicker than they could be solved using a single computer.","order":4,"origin":"template"},{"id":"c-CSN-2.B.5","parentId":"c-CSN-2.B","code":"CSN-2.B.5","text":"When increasing the use of parallel computing in a solution, the efficiency of the solution is still limited by the sequential portion. This means that at some point, adding parallel portions will no longer meaningfully increase efficiency.","order":5,"origin":"template"},{"id":"c-IOC-1.A","parentId":"c-5.1","code":"IOC-1.A","text":"Explain how an effect of a computing innovation can be both beneficial and harmful.","order":1,"origin":"template","meta":{"enduringUnderstanding":"IOC-1: While computing innovations are typically designed to achieve a specific purpose, they may have unintended consequences."}},{"id":"c-IOC-1.A.1","parentId":"c-IOC-1.A","code":"IOC-1.A.1","text":"People create computing innovations.","order":1,"origin":"template"},{"id":"c-IOC-1.A.2","parentId":"c-IOC-1.A","code":"IOC-1.A.2","text":"The way people complete tasks often changes to incorporate new computing innovations.","order":2,"origin":"template"},{"id":"c-IOC-1.A.3","parentId":"c-IOC-1.A","code":"IOC-1.A.3","text":"Not every effect of a computing innovation is anticipated in advance.","order":3,"origin":"template"},{"id":"c-IOC-1.A.4","parentId":"c-IOC-1.A","code":"IOC-1.A.4","text":"A single effect can be viewed as both beneficial and harmful by different people, or even by the same person.","order":4,"origin":"template"},{"id":"c-IOC-1.A.5","parentId":"c-IOC-1.A","code":"IOC-1.A.5","text":"Advances in computing have generated and increased creativity in other fields, such as medicine, engineering, communications, and the arts.","order":5,"origin":"template"},{"id":"c-IOC-1.B","parentId":"c-5.1","code":"IOC-1.B","text":"Explain how a computing innovation can have an impact beyond its intended purpose.","order":2,"origin":"template","meta":{"enduringUnderstanding":"IOC-1: While computing innovations are typically designed to achieve a specific purpose, they may have unintended consequences."}},{"id":"c-IOC-1.B.1","parentId":"c-IOC-1.B","code":"IOC-1.B.1","text":"Computing innovations can be used in ways that their creators had not originally intended: The World Wide Web was originally intended only for rapid and easy exchange of information within the scientific community.","order":1,"origin":"template"},{"id":"c-IOC-1.B.2","parentId":"c-IOC-1.B","code":"IOC-1.B.2","text":"Some of the ways computing innovations can be used may have a harmful impact on society, the economy, or culture.","order":2,"origin":"template"},{"id":"c-IOC-1.B.3","parentId":"c-IOC-1.B","code":"IOC-1.B.3","text":"Responsible programmers try to consider the unintended ways their computing innovations can be used and the potential beneficial and harmful effects of these new uses.","order":3,"origin":"template"},{"id":"c-IOC-1.B.4","parentId":"c-IOC-1.B","code":"IOC-1.B.4","text":"It is not possible for a programmer to consider all the ways a computing innovation can be used.","order":4,"origin":"template"},{"id":"c-IOC-1.B.5","parentId":"c-IOC-1.B","code":"IOC-1.B.5","text":"Computing innovations have often had unintended beneficial effects by leading to advances in other fields.","order":5,"origin":"template"},{"id":"c-IOC-1.B.6","parentId":"c-IOC-1.B","code":"IOC-1.B.6","text":"Rapid sharing of a program or running a program with a large number of users can result in significant impacts beyond the intended purpose or control of the programmer.","order":6,"origin":"template"},{"id":"c-IOC-1.C","parentId":"c-5.2","code":"IOC-1.C","text":"Describe issues that contribute to the digital divide.","order":1,"origin":"template","meta":{"enduringUnderstanding":"IOC-1: While computing innovations are typically designed to achieve a specific purpose, they may have unintended consequences."}},{"id":"c-IOC-1.C.1","parentId":"c-IOC-1.C","code":"IOC-1.C.1","text":"Internet access varies between socioeconomic, geographic, and demographic characteristics, as well as between countries.","order":1,"origin":"template"},{"id":"c-IOC-1.C.2","parentId":"c-IOC-1.C","code":"IOC-1.C.2","text":"The “digital divide” refers to differing access to computing devices and the Internet, based on socioeconomic, geographic, or demographic characteristics.","order":2,"origin":"template"},{"id":"c-IOC-1.C.3","parentId":"c-IOC-1.C","code":"IOC-1.C.3","text":"The digital divide can affect both groups and individuals.","order":3,"origin":"template"},{"id":"c-IOC-1.C.4","parentId":"c-IOC-1.C","code":"IOC-1.C.4","text":"The digital divide raises issues of equity, access, and influence, both globally and locally.","order":4,"origin":"template"},{"id":"c-IOC-1.C.5","parentId":"c-IOC-1.C","code":"IOC-1.C.5","text":"The digital divide is affected by the actions of individuals, organizations, and governments.","order":5,"origin":"template"},{"id":"c-IOC-1.D","parentId":"c-5.3","code":"IOC-1.D","text":"Explain how bias exists in computing innovations.","order":1,"origin":"template","meta":{"enduringUnderstanding":"IOC-1: While computing innovations are typically designed to achieve a specific purpose, they may have unintended consequences.","skills":["5.E"]}},{"id":"c-IOC-1.D.1","parentId":"c-IOC-1.D","code":"IOC-1.D.1","text":"Computing innovations can reflect existing human biases because of biases written into the algorithms or biases in the data used by the innovation.","order":1,"origin":"template"},{"id":"c-IOC-1.D.2","parentId":"c-IOC-1.D","code":"IOC-1.D.2","text":"Programmers should take action to reduce bias in algorithms used for computing innovations as a way of combating existing human biases.","order":2,"origin":"template"},{"id":"c-IOC-1.D.3","parentId":"c-IOC-1.D","code":"IOC-1.D.3","text":"Biases can be embedded at all levels of software development.","order":3,"origin":"template"},{"id":"c-IOC-1.E","parentId":"c-5.4","code":"IOC-1.E","text":"Explain how people participate in problem-solving processes at scale.","order":1,"origin":"template","meta":{"enduringUnderstanding":"IOC-1: While computing innovations are typically designed to achieve a specific purpose, they may have unintended consequences.","skills":["1.C"]}},{"id":"c-IOC-1.E.1","parentId":"c-IOC-1.E","code":"IOC-1.E.1","text":"Widespread access to information and public data facilitates the identification of problems, development of solutions, and dissemination of results.","order":1,"origin":"template"},{"id":"c-IOC-1.E.2","parentId":"c-IOC-1.E","code":"IOC-1.E.2","text":"Science has been affected by using distributed and “citizen science” to solve scientific problems.","order":2,"origin":"template"},{"id":"c-IOC-1.E.3","parentId":"c-IOC-1.E","code":"IOC-1.E.3","text":"Citizen science is scientific research conducted in whole or part by distributed individuals, many of whom may not be scientists, who contribute relevant data to research using their own computing devices.","order":3,"origin":"template"},{"id":"c-IOC-1.E.4","parentId":"c-IOC-1.E","code":"IOC-1.E.4","text":"Crowdsourcing is the practice of obtaining input or information from a large number of people via the Internet.","order":4,"origin":"template"},{"id":"c-IOC-1.E.5","parentId":"c-IOC-1.E","code":"IOC-1.E.5","text":"Human capabilities can be enhanced by collaboration via computing.","order":5,"origin":"template"},{"id":"c-IOC-1.E.6","parentId":"c-IOC-1.E","code":"IOC-1.E.6","text":"Crowdsourcing offers new models for collaboration, such as connecting businesses or social causes with funding.","order":6,"origin":"template"},{"id":"c-IOC-1.F","parentId":"c-5.5","code":"IOC-1.F","text":"Explain how the use of computing can raise legal and ethical concerns.","order":1,"origin":"template","meta":{"enduringUnderstanding":"IOC-1: While computing innovations are typically designed to achieve a specific purpose, they may have unintended consequences.","skills":["5.E"]}},{"id":"c-IOC-1.F.1","parentId":"c-IOC-1.F","code":"IOC-1.F.1","text":"Material created on a computer is the intellectual property of the creator or an organization.","order":1,"origin":"template"},{"id":"c-IOC-1.F.2","parentId":"c-IOC-1.F","code":"IOC-1.F.2","text":"Ease of access and distribution of digitized information raises intellectual property concerns regarding ownership, value, and use.","order":2,"origin":"template"},{"id":"c-IOC-1.F.3","parentId":"c-IOC-1.F","code":"IOC-1.F.3","text":"Measures should be taken to safeguard intellectual property.","order":3,"origin":"template"},{"id":"c-IOC-1.F.4","parentId":"c-IOC-1.F","code":"IOC-1.F.4","text":"The use of material created by someone else without permission and presented as one’s own is plagiarism and may have legal consequences.","order":4,"origin":"template"},{"id":"c-IOC-1.F.5","parentId":"c-IOC-1.F","code":"IOC-1.F.5","text":"Some examples of legal ways to use materials created by someone else include:","order":5,"origin":"template"},{"id":"c-IOC-1.F.6","parentId":"c-IOC-1.F","code":"IOC-1.F.6","text":"The use of material created by someone other than you should always be cited.","order":6,"origin":"template"},{"id":"c-IOC-1.F.7","parentId":"c-IOC-1.F","code":"IOC-1.F.7","text":"Creative Commons, open source, and open access have enabled broad access to digital information.","order":7,"origin":"template"},{"id":"c-IOC-1.F.8","parentId":"c-IOC-1.F","code":"IOC-1.F.8","text":"As with any technology or medium, using computing to harm individuals or groups of people raises legal and ethical concerns.","order":8,"origin":"template"},{"id":"c-IOC-1.F.9","parentId":"c-IOC-1.F","code":"IOC-1.F.9","text":"Computing can play a role in social and political issues, which in turn often raises legal and ethical concerns.","order":9,"origin":"template"},{"id":"c-IOC-1.F.10","parentId":"c-IOC-1.F","code":"IOC-1.F.10","text":"The digital divide raises ethical concerns around computing.","order":10,"origin":"template"},{"id":"c-IOC-1.F.11","parentId":"c-IOC-1.F","code":"IOC-1.F.11","text":"Computing innovations can raise legal and ethical concerns. Some examples of these include:","order":11,"origin":"template"},{"id":"c-IOC-2.A","parentId":"c-5.6","code":"IOC-2.A","text":"Describe the risks to privacy from collecting and storing personal data on a computer system.","order":1,"origin":"template","meta":{"enduringUnderstanding":"IOC-2: The use of computing innovations may involve risks to personal safety and identity.","skills":["5.D"]}},{"id":"c-IOC-2.A.1","parentId":"c-IOC-2.A","code":"IOC-2.A.1","text":"Personally identifiable information (PII) is information about an individual that identifies, links, relates, or describes them. Examples of PII include:","order":1,"origin":"template"},{"id":"c-IOC-2.A.2","parentId":"c-IOC-2.A","code":"IOC-2.A.2","text":"Search engines can record and maintain a history of searches made by users.","order":2,"origin":"template"},{"id":"c-IOC-2.A.3","parentId":"c-IOC-2.A","code":"IOC-2.A.3","text":"Websites can record and maintain a history of individuals who have viewed their pages.","order":3,"origin":"template"},{"id":"c-IOC-2.A.4","parentId":"c-IOC-2.A","code":"IOC-2.A.4","text":"Devices, websites, and networks can collect information about a user’s location.","order":4,"origin":"template"},{"id":"c-IOC-2.A.5","parentId":"c-IOC-2.A","code":"IOC-2.A.5","text":"Technology enables the collection, use, and exploitation of information about, by, and for individuals, groups, and institutions.","order":5,"origin":"template"},{"id":"c-IOC-2.A.6","parentId":"c-IOC-2.A","code":"IOC-2.A.6","text":"Search engines can use search history to suggest websites or for targeted marketing.","order":6,"origin":"template"},{"id":"c-IOC-2.A.7","parentId":"c-IOC-2.A","code":"IOC-2.A.7","text":"Disparate personal data, such as geolocation, cookies, and browsing history, can be aggregated to create knowledge about an individual.","order":7,"origin":"template"},{"id":"c-IOC-2.A.8","parentId":"c-IOC-2.A","code":"IOC-2.A.8","text":"PII and other information placed online can be used to enhance a user’s online experiences.","order":8,"origin":"template"},{"id":"c-IOC-2.A.9","parentId":"c-IOC-2.A","code":"IOC-2.A.9","text":"PII stored online can be used to simplify making online purchases.","order":9,"origin":"template"},{"id":"c-IOC-2.A.10","parentId":"c-IOC-2.A","code":"IOC-2.A.10","text":"Commercial and governmental curation of information may be exploited if privacy and other protections are ignored.","order":10,"origin":"template"},{"id":"c-IOC-2.A.11","parentId":"c-IOC-2.A","code":"IOC-2.A.11","text":"Information placed online can be used in ways that were not intended and that may have a harmful impact. For example, an email message may be forwarded, tweets can be retweeted, and social media posts can be viewed by potential employers.","order":11,"origin":"template"},{"id":"c-IOC-2.A.12","parentId":"c-IOC-2.A","code":"IOC-2.A.12","text":"PII can be used to stalk or steal the identity of a person or to aid in the planning of other criminal acts.","order":12,"origin":"template"},{"id":"c-IOC-2.A.13","parentId":"c-IOC-2.A","code":"IOC-2.A.13","text":"Once information is placed online, it is difficult to delete.","order":13,"origin":"template"},{"id":"c-IOC-2.A.14","parentId":"c-IOC-2.A","code":"IOC-2.A.14","text":"Programs can collect your location and record where you have been, how you got there, and how long you were at a given location.","order":14,"origin":"template"},{"id":"c-IOC-2.A.15","parentId":"c-IOC-2.A","code":"IOC-2.A.15","text":"Information posted to social media services can be used by others. Combining information posted on social media and other sources can be used to deduce private information about you.","order":15,"origin":"template"},{"id":"c-IOC-2.B","parentId":"c-5.6","code":"IOC-2.B","text":"Explain how computing resources can be protected and can be misused.","order":2,"origin":"template","meta":{"enduringUnderstanding":"IOC-2: The use of computing innovations may involve risks to personal safety and identity.","skills":["5.E"]}},{"id":"c-IOC-2.B.1","parentId":"c-IOC-2.B","code":"IOC-2.B.1","text":"Authentication measures protect devices and information from unauthorized access. Examples of authentication measures include strong passwords and multifactor authentication.","order":1,"origin":"template"},{"id":"c-IOC-2.B.2","parentId":"c-IOC-2.B","code":"IOC-2.B.2","text":"A strong password is something that is easy for a user to remember but would be difficult for someone else to guess based on knowledge of that user.","order":2,"origin":"template"},{"id":"c-IOC-2.B.3","parentId":"c-IOC-2.B","code":"IOC-2.B.3","text":"Multifactor authentication is a method of computer access control in which a user is only granted access after successfully presenting several separate pieces of evidence to an authentication mechanism, typically in at least two of the following categories: knowledge (something they know), possession (something they have), and inherence (something they are).","order":3,"origin":"template"},{"id":"c-IOC-2.B.4","parentId":"c-IOC-2.B","code":"IOC-2.B.4","text":"Multifactor authentication requires at least two steps to unlock protected information; each step adds a new layer of security that must be broken to gain unauthorized access.","order":4,"origin":"template"},{"id":"c-IOC-2.B.5","parentId":"c-IOC-2.B","code":"IOC-2.B.5","text":"Encryption is the process of encoding data to prevent unauthorized access. Decryption is the process of decoding the data. Two common encryption approaches are:","order":5,"origin":"template"},{"id":"c-IOC-2.B.6","parentId":"c-IOC-2.B","code":"IOC-2.B.6","text":"Certificate authorities issue digital certificates that validate the ownership of encryption keys used in secure communications and are based on a trust model.","order":6,"origin":"template"},{"id":"c-IOC-2.B.7","parentId":"c-IOC-2.B","code":"IOC-2.B.7","text":"Computer virus and malware scanning software can help protect a computing system against infection.","order":7,"origin":"template"},{"id":"c-IOC-2.B.8","parentId":"c-IOC-2.B","code":"IOC-2.B.8","text":"A computer virus is a malicious program that can copy itself and gain access to a computer in an unauthorized way. Computer viruses often attach themselves to legitimate programs and start running independently on a computer.","order":8,"origin":"template"},{"id":"c-IOC-2.B.9","parentId":"c-IOC-2.B","code":"IOC-2.B.9","text":"Malware is software intended to damage a computing system or to take partial control over its operation.","order":9,"origin":"template"},{"id":"c-IOC-2.B.10","parentId":"c-IOC-2.B","code":"IOC-2.B.10","text":"All real-world systems have errors or design flaws that can be exploited to compromise them. Regular software updates help fix errors that could compromise a computing system.","order":10,"origin":"template"},{"id":"c-IOC-2.B.11","parentId":"c-IOC-2.B","code":"IOC-2.B.11","text":"Users can control the permissions programs have for collecting user information. Users should review the permission settings of programs to protect their privacy.","order":11,"origin":"template"},{"id":"c-IOC-2.C","parentId":"c-5.6","code":"IOC-2.C","text":"Explain how unauthorized access to computing resources is gained.","order":3,"origin":"template","meta":{"enduringUnderstanding":"IOC-2: The use of computing innovations may involve risks to personal safety and identity.","skills":["5.E"]}},{"id":"c-IOC-2.C.1","parentId":"c-IOC-2.C","code":"IOC-2.C.1","text":"Phishing is a technique that attempts to trick a user into providing personal information. That personal information can then be used to access sensitive online resources, such as bank accounts and emails.","order":1,"origin":"template"},{"id":"c-IOC-2.C.2","parentId":"c-IOC-2.C","code":"IOC-2.C.2","text":"Keylogging is the use of a program to record every keystroke made by a computer user in order to gain fraudulent access to passwords and other confidential information.","order":2,"origin":"template"},{"id":"c-IOC-2.C.3","parentId":"c-IOC-2.C","code":"IOC-2.C.3","text":"Data sent over public networks can be intercepted, analyzed, and modified. One way that this can happen is through a rogue access point.","order":3,"origin":"template"},{"id":"c-IOC-2.C.4","parentId":"c-IOC-2.C","code":"IOC-2.C.4","text":"A rogue access point is a wireless access point that gives unauthorized access to secure networks.","order":4,"origin":"template"},{"id":"c-IOC-2.C.5","parentId":"c-IOC-2.C","code":"IOC-2.C.5","text":"A malicious link can be disguised on a web page or in an email message.","order":5,"origin":"template"},{"id":"c-IOC-2.C.6","parentId":"c-IOC-2.C","code":"IOC-2.C.6","text":"Unsolicited emails, attachments, links, and forms in emails can be used to compromise the security of a computing system. These can come from unknown senders or from known senders whose security has been compromised.","order":6,"origin":"template"},{"id":"c-IOC-2.C.7","parentId":"c-IOC-2.C","code":"IOC-2.C.7","text":"Untrustworthy (often free) downloads from freeware or shareware sites can contain malware.","order":7,"origin":"template"}]},{"id":"practices","name":"AP CSP computational thinking practices","levels":["Practice","Skill"],"nodes":[{"id":"p-1","parentId":null,"code":"1","text":"Computational Solution Design","order":1,"origin":"template","meta":{"description":"Design and evaluate computational solutions for a purpose."}},{"id":"p-2","parentId":null,"code":"2","text":"Algorithms and Program Development","order":2,"origin":"template","meta":{"description":"Develop and implement algorithms."}},{"id":"p-3","parentId":null,"code":"3","text":"Abstraction in Program Development","order":3,"origin":"template","meta":{"description":"Develop programs that incorporate abstractions."}},{"id":"p-4","parentId":null,"code":"4","text":"Code Analysis","order":4,"origin":"template","meta":{"description":"Evaluate and test algorithms and programs."}},{"id":"p-5","parentId":null,"code":"5","text":"Computing Innovations","order":5,"origin":"template","meta":{"description":"Investigate computing innovations."}},{"id":"p-6","parentId":null,"code":"6","text":"Responsible Computing","order":6,"origin":"template","meta":{"description":"Contribute to an inclusive, safe, collaborative, and ethical computing culture."}},{"id":"p-1.A","parentId":"p-1","code":"1.A","text":"Investigate the situation, context, or task.","order":1,"origin":"template"},{"id":"p-1.B","parentId":"p-1","code":"1.B","text":"Determine and design an appropriate method or approach to achieve the purpose.","order":2,"origin":"template"},{"id":"p-1.C","parentId":"p-1","code":"1.C","text":"Explain how collaboration affects the development of a solution.","order":3,"origin":"template"},{"id":"p-1.D","parentId":"p-1","code":"1.D","text":"Evaluate solution options.","order":4,"origin":"template"},{"id":"p-2.A","parentId":"p-2","code":"2.A","text":"Represent algorithmic processes without using a programming language.","order":1,"origin":"template"},{"id":"p-2.B","parentId":"p-2","code":"2.B","text":"Implement and apply an algorithm.","order":2,"origin":"template"},{"id":"p-3.A","parentId":"p-3","code":"3.A","text":"Generalize data sources through variables.","order":1,"origin":"template"},{"id":"p-3.B","parentId":"p-3","code":"3.B","text":"Use abstraction to manage complexity in a program.","order":2,"origin":"template"},{"id":"p-3.C","parentId":"p-3","code":"3.C","text":"Explain how abstraction manages complexity.","order":3,"origin":"template"},{"id":"p-4.A","parentId":"p-4","code":"4.A","text":"Explain how a code segment or program functions.","order":1,"origin":"template"},{"id":"p-4.B","parentId":"p-4","code":"4.B","text":"Determine the result of code segments.","order":2,"origin":"template"},{"id":"p-4.C","parentId":"p-4","code":"4.C","text":"Identify and correct errors in algorithms and programs, including error discovery through testing.","order":3,"origin":"template"},{"id":"p-5.A","parentId":"p-5","code":"5.A","text":"Explain how computing systems work.","order":1,"origin":"template"},{"id":"p-5.B","parentId":"p-5","code":"5.B","text":"Explain how knowledge can be generated from data.","order":2,"origin":"template"},{"id":"p-5.C","parentId":"p-5","code":"5.C","text":"Describe the impact of a computing innovation.","order":3,"origin":"template"},{"id":"p-5.D","parentId":"p-5","code":"5.D","text":"Describe the impact of gathering data.","order":4,"origin":"template"},{"id":"p-5.E","parentId":"p-5","code":"5.E","text":"Evaluate the use of computing based on legal and ethical factors.","order":5,"origin":"template"},{"id":"p-6.A","parentId":"p-6","code":"6.A","text":"Collaborate in the development of solutions.","order":1,"origin":"template"},{"id":"p-6.B","parentId":"p-6","code":"6.B","text":"Use safe and secure methods when using computing devices.","order":2,"origin":"template"},{"id":"p-6.C","parentId":"p-6","code":"6.C","text":"Acknowledge the intellectual property of others.","order":3,"origin":"template"}]}],"suggestedSkills":{"c-1.1":["p-1.C","p-6.A"],"c-1.2":["p-1.A","p-3.A","p-4.A"],"c-1.3":["p-1.B","p-1.C","p-4.A","p-6.C"],"c-1.4":["p-1.B","p-4.C"],"c-2.1":["p-1.D","p-2.B","p-3.C"],"c-2.2":["p-1.D"],"c-2.3":["p-5.B","p-5.D"],"c-2.4":["p-2.B","p-5.B"],"c-3.1":["p-3.A","p-4.B"],"c-3.2":["p-3.A","p-3.B","p-3.C"],"c-3.3":["p-2.A","p-2.B","p-4.B"],"c-3.4":["p-4.B"],"c-3.5":["p-2.B","p-4.B"],"c-3.6":["p-2.A","p-2.B","p-4.B"],"c-3.7":["p-2.B","p-4.B"],"c-3.8":["p-2.A","p-2.B","p-4.B"],"c-3.9":["p-1.D","p-2.A","p-2.B"],"c-3.10":["p-2.B","p-4.B"],"c-3.11":["p-1.A","p-1.D"],"c-3.12":["p-3.B","p-4.B"],"c-3.13":["p-3.B","p-3.C"],"c-3.14":["p-2.B"],"c-3.15":["p-2.B","p-4.B"],"c-3.16":["p-1.A","p-1.D"],"c-3.17":["p-1.D"],"c-3.18":["p-1.A"],"c-4.1":["p-5.A"],"c-4.2":["p-1.D","p-5.A"],"c-4.3":["p-1.D"],"c-5.1":["p-5.C"],"c-5.2":["p-5.C"],"c-5.3":["p-5.E"],"c-5.4":["p-1.C"],"c-5.5":["p-5.E"],"c-5.6":["p-5.D","p-5.E"]},"activityBank":[]}};
